// Package penalty holds everything about a penalty kick that is pure
// computation: the constants a game is played with, the ten parameters of a
// kick, how 32 bytes of entropy map onto them, the shootout rules, and
// SimulateShot.
//
// It has no state and no realm dependencies, so every version of the game
// realm agrees on these types, and a client can run the same code to check a
// result. All quantities are integers: millimetres, mm/s, milliseconds,
// per-mille (0..1000) and milli-radii (thousandths of the ball's radius), so
// the outcome is identical on every node.
package penalty

import (
	"errors"
	"strconv"
	"strings"
)

// Config is the set of keeper and ball constants a game is created with.
type Config struct {
	GoalWidth  int64 // inside width, mm
	GoalHeight int64 // inside height, mm

	KeeperScale int64 // keeper size relative to a ~1.85 m keeper, per-mille
	ReactionMin int64 // keeper reaction delay range, ms
	ReactionMax int64
	StarShare   int64 // share of the keeper's speed range that means "star jump", per-mille
	ReadShare   int64 // share that means "wait and read the shot", per-mille
	DiveMin     int64 // committed dive speed range, mm/s
	DiveMax     int64
	JumpMin     int64 // keeper vertical launch speed range, mm/s (negative = collapse low)
	JumpMax     int64

	BallMinSpeed int64 // ball speed at 0% power, mm/s
	BallMaxSpeed int64 // ball speed at 100% power, mm/s
	FuzzBase     int64 // std-dev of the mishit at 0% power, milli-radii
	FuzzPower    int64 // extra std-dev at 100% power, milli-radii
	MaxContact   int64 // farthest contact offset a taker may choose, milli-radii
}

// DefaultConfig returns the constants the reference simulation is tuned for.
func DefaultConfig() Config {
	return Config{
		GoalWidth:    6555,
		GoalHeight:   2424,
		KeeperScale:  1176,
		ReactionMin:  20,
		ReactionMax:  120,
		StarShare:    60,
		ReadShare:    240, // as the browser engine (PLAN.READ_SHARE)
		DiveMin:      2600,
		DiveMax:      5200,
		JumpMin:      -1400,
		JumpMax:      4000,
		BallMinSpeed: 10000,
		BallMaxSpeed: 34000,
		FuzzBase:     30,
		FuzzPower:    100,
		MaxContact:   500,
	}
}

type bound struct {
	name   string
	lo, hi int64
}

// The range each constant may be set to, so a game cannot be created with
// physics the simulation was never meant to handle. Order matches field().
var bounds = []bound{
	{"goalWidth", 5000, 7320},
	{"goalHeight", 1800, 2440},
	{"keeperScale", 900, 1300},
	{"reactionMin", 0, 300},
	{"reactionMax", 0, 400},
	{"starShare", 0, 300},
	{"readShare", 0, 700},
	{"diveMin", 1500, 7000},
	{"diveMax", 1500, 7000},
	{"jumpMin", -2500, 0},
	{"jumpMax", 0, 5000},
	{"ballMinSpeed", 5000, 40000},
	{"ballMaxSpeed", 5000, 40000},
	{"fuzzBase", 0, 150},
	{"fuzzPower", 0, 300},
	{"maxContact", 200, 800},
}

func (c *Config) field(i int) *int64 {
	switch i {
	case 0:
		return &c.GoalWidth
	case 1:
		return &c.GoalHeight
	case 2:
		return &c.KeeperScale
	case 3:
		return &c.ReactionMin
	case 4:
		return &c.ReactionMax
	case 5:
		return &c.StarShare
	case 6:
		return &c.ReadShare
	case 7:
		return &c.DiveMin
	case 8:
		return &c.DiveMax
	case 9:
		return &c.JumpMin
	case 10:
		return &c.JumpMax
	case 11:
		return &c.BallMinSpeed
	case 12:
		return &c.BallMaxSpeed
	case 13:
		return &c.FuzzBase
	case 14:
		return &c.FuzzPower
	case 15:
		return &c.MaxContact
	}
	panic("penalty: no config field " + strconv.Itoa(i))
}

var (
	ErrConfigRange   = errors.New("penalty: config value out of range")
	ErrConfigOrder   = errors.New("penalty: config range is inverted")
	ErrConfigShares  = errors.New("penalty: starShare + readShare must not exceed 900")
	ErrConfigUnknown = errors.New("penalty: unknown config key")
	ErrConfigSyntax  = errors.New("penalty: config must be key=value pairs separated by commas")
)

// Validate checks every constant against its allowed range.
func (c Config) Validate() error {
	for i, b := range bounds {
		v := *c.field(i)
		if v < b.lo || v > b.hi {
			return errors.New(ErrConfigRange.Error() + ": " + b.name + "=" + strconv.FormatInt(v, 10) +
				" (allowed " + strconv.FormatInt(b.lo, 10) + ".." + strconv.FormatInt(b.hi, 10) + ")")
		}
	}
	if c.ReactionMin > c.ReactionMax || c.DiveMin > c.DiveMax ||
		c.JumpMin > c.JumpMax || c.BallMinSpeed > c.BallMaxSpeed {
		return ErrConfigOrder
	}
	if c.StarShare+c.ReadShare > 900 {
		return ErrConfigShares
	}
	return nil
}

// ParseConfig applies "key=value,key=value" overrides to DefaultConfig and
// validates the result. An empty string gives the defaults. Keys are the
// lower-camel names String prints, e.g. "goalWidth=6400,reactionMax=150".
func ParseConfig(s string) (Config, error) {
	c := DefaultConfig()
	s = strings.TrimSpace(s)
	if s != "" {
		for _, kv := range strings.Split(s, ",") {
			parts := strings.Split(strings.TrimSpace(kv), "=")
			if len(parts) != 2 {
				return Config{}, ErrConfigSyntax
			}
			key := strings.TrimSpace(parts[0])
			v, err := strconv.ParseInt(strings.TrimSpace(parts[1]), 10, 64)
			if err != nil {
				return Config{}, ErrConfigSyntax
			}
			found := false
			for i, b := range bounds {
				if b.name == key {
					*c.field(i) = v
					found = true
					break
				}
			}
			if !found {
				return Config{}, errors.New(ErrConfigUnknown.Error() + ": " + key)
			}
		}
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

// String prints the config in the form ParseConfig accepts.
func (c Config) String() string {
	var b strings.Builder
	for i, bd := range bounds {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(bd.name + "=" + strconv.FormatInt(*c.field(i), 10))
	}
	return b.String()
}

package penalty

import (
	"errors"
	"strconv"
)

const (
	BallRadius = 110   // mm
	PostRadius = 60    // mm
	Distance   = 11000 // penalty spot to goal line, mm
	Gravity    = 9810  // mm/s²

	AimMaxX = 6000 // the aim point must lie within ±6 m of the goal centre
	AimMaxY = 4000 // and between the grass and 4 m up
)

// ShotInput is what a taker chooses: the five numbers a player sends.
type ShotInput struct {
	AimX     int64 // point on the goal plane the swing heads for, mm from the centre (+ = taker's right)
	AimY     int64 // its height, mm
	ContactX int64 // where the boot meets the ball, milli-radii from its centre (+ = right)
	ContactY int64 // milli-radii (+ = above centre)
	Power    int64 // per-mille
}

// ShotParams is a complete kick: the taker's five choices plus the 24-byte
// mishit seed that decides how far the boot lands from the chosen contact.
// These six, with a keeper's four, are the ten inputs of SimulateShot.
type ShotParams struct {
	AimX     int64
	AimY     int64
	ContactX int64
	ContactY int64
	Power    int64
	Mishit   [24]byte
}

// KeeperPlan is the keeper's commitment: four uint16 values that DecodePlan
// maps onto a dive using the game's Config.
type KeeperPlan struct {
	Direction uint16
	Speed     uint16
	Jump      uint16
	Reaction  uint16
}

var ErrShotRange = errors.New("penalty: shot parameter out of range")

// Validate checks a taker's choices against the game's constants.
func (s ShotInput) Validate(c Config) error {
	if s.AimX < -AimMaxX || s.AimX > AimMaxX {
		return errors.New(ErrShotRange.Error() + ": aimX must be within ±" + strconv.Itoa(AimMaxX) + " mm")
	}
	if s.AimY < 0 || s.AimY > AimMaxY {
		return errors.New(ErrShotRange.Error() + ": aimY must be within 0.." + strconv.Itoa(AimMaxY) + " mm")
	}
	if s.ContactX*s.ContactX+s.ContactY*s.ContactY > c.MaxContact*c.MaxContact {
		return errors.New(ErrShotRange.Error() + ": contact offset must be within " +
			strconv.FormatInt(c.MaxContact, 10) + " milli-radii of the centre")
	}
	if s.Power < 0 || s.Power > 1000 {
		return errors.New(ErrShotRange.Error() + ": power must be within 0..1000")
	}
	return nil
}

// WithMishit completes a taker's choices with a mishit seed.
func (s ShotInput) WithMishit(m [24]byte) ShotParams {
	return ShotParams{AimX: s.AimX, AimY: s.AimY, ContactX: s.ContactX, ContactY: s.ContactY, Power: s.Power, Mishit: m}
}

// Input returns the taker's five choices.
func (s ShotParams) Input() ShotInput {
	return ShotInput{AimX: s.AimX, AimY: s.AimY, ContactX: s.ContactX, ContactY: s.ContactY, Power: s.Power}
}

func (s ShotInput) String() string {
	return "aim=(" + strconv.FormatInt(s.AimX, 10) + "," + strconv.FormatInt(s.AimY, 10) + ")mm contact=(" +
		strconv.FormatInt(s.ContactX, 10) + "," + strconv.FormatInt(s.ContactY, 10) + ")mR power=" +
		strconv.FormatInt(s.Power, 10) + "‰"
}

func (p KeeperPlan) String() string {
	return "plan=(" + strconv.Itoa(int(p.Direction)) + "," + strconv.Itoa(int(p.Speed)) + "," +
		strconv.Itoa(int(p.Jump)) + "," + strconv.Itoa(int(p.Reaction)) + ")"
}

package penalty

// Mode is what kind of move a keeper plan describes.
type Mode uint8

const (
	ModeStar Mode = iota + 1 // spread into a star jump
	ModeRead                 // hold and react to the shot
	ModeDive                 // commit to a dive
)

func (m Mode) String() string {
	switch m {
	case ModeStar:
		return "star jump"
	case ModeRead:
		return "wait and read"
	case ModeDive:
		return "committed dive"
	}
	return "unknown"
}

// Plan is a KeeperPlan decoded with a game's constants.
type Plan struct {
	Mode     Mode
	Heading  int64 // deci-degrees: 0 = along the line to the taker's right, 1800 = to the left, 900 = straight out
	Speed    int64 // mm/s along the ground (0 for a read)
	Jump     int64 // mm/s upwards (negative = collapse low)
	Reaction int64 // ms after contact before moving
}

// Dive headings stay within ForwardMax of the line, except for the middle
// CentreShare of the direction range, which sweeps the headings in between.
const (
	ForwardMax  = 220 // deci-degrees
	CentreShare = 60  // per-mille of the direction range
	StarMaxSpd  = 1150
)

// DecodePlan maps the four uint16 of a keeper plan onto a move:
//
//	direction  monotonic 0..65535 -> heading 0°..180°
//	speed      lowest StarShare -> star jump, next ReadShare -> wait and read,
//	           the rest -> dive at DiveMin..DiveMax
//	jump       JumpMin..JumpMax
//	reaction   ReactionMin..ReactionMax
//
// For a read plan the direction and jump are unused: the keeper decides them
// from the ball.
func DecodePlan(p KeeperPlan, c Config) Plan {
	out := Plan{
		Heading:  heading(p.Direction),
		Jump:     span(p.Jump, c.JumpMin, c.JumpMax),
		Reaction: span(p.Reaction, c.ReactionMin, c.ReactionMax),
	}
	u := int64(p.Speed)
	starEdge := 65535 * c.StarShare / 1000
	readEdge := 65535 * (c.StarShare + c.ReadShare) / 1000
	switch {
	case u < starEdge:
		out.Mode = ModeStar
		out.Speed = StarMaxSpd * u / starEdge
	case u < readEdge:
		out.Mode = ModeRead
	default:
		out.Mode = ModeDive
		out.Speed = c.DiveMin + (c.DiveMax-c.DiveMin)*(u-readEdge)/maxI(1, 65535-readEdge)
	}
	return out
}

func heading(d uint16) int64 {
	s := 2*int64(d) - 65535 // -65535 (right) .. 65535 (left)
	c := int64(65535 * CentreShare / 1000)
	switch {
	case s <= -c:
		return ForwardMax * (65535 + s) / (65535 - c)
	case s >= c:
		return 1800 - ForwardMax*(65535-s)/(65535-c)
	}
	return 900 + (900-ForwardMax)*s/c
}

// cosPermille approximates cos(heading) × 1000 (Bhaskara I), heading in
// deci-degrees within 0..1800. Integer-only, accurate to about 0.2%.
func cosPermille(h int64) int64 {
	sign := int64(1)
	if h > 900 {
		h = 1800 - h
		sign = -1
	}
	d2 := h * h // (deci-degrees)²
	return sign * 1000 * (3240000 - 4*d2) / (3240000 + d2)
}

func maxI(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func minI(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func absI(a int64) int64 {
	if a < 0 {
		return -a
	}
	return a
}

func clampI(x, lo, hi int64) int64 {
	if x < lo {
		return lo
	}
	if x > hi {
		return hi
	}
	return x
}

package penalty

// Seed is the 32 bytes of entropy that complete a kick.
//
// When the player shoots, the seed supplies the computer's keeper and the
// player's mishit:
//
//	bytes 0-7    keeper plan: four big-endian uint16 (direction, speed, jump, reaction)
//	bytes 8-31   mishit seed (24 bytes)
//
// When the player keeps, the seed supplies the computer's whole kick:
//
//	bytes 0-1    aim x       uint16 -> ±(GoalWidth/2 - ChainAimInset) mm
//	bytes 2-3    aim y       uint16 -> ChainAimMinY .. GoalHeight + ChainAimOverY mm
//	bytes 4-5    power       uint16 -> ChainPowerMin .. 1000 per-mille
//	byte  6      contact x   int8   -> ±ChainContact milli-radii
//	byte  7      contact y   int8   -> ±ChainContact milli-radii
//	bytes 8-31   mishit seed (24 bytes)
//
// So the layout is the same either way: the first eight bytes are "the
// computer's move", the last twenty-four are the mishit.
type Seed [32]byte

// How the computer takes its kicks: inside the frame, aimed a little high to
// allow for the drop, struck with at least ChainPowerMin.
const (
	ChainAimInset = 250 // mm inside each post
	ChainAimMinY  = 300 // mm
	ChainAimOverY = 200 // mm above the bar at most
	ChainPowerMin = 450 // per-mille
	ChainContact  = 350 // milli-radii
)

func u16(b []byte) uint16 { return uint16(b[0])<<8 | uint16(b[1]) }

// span maps a uint16 linearly onto lo..hi.
func span(u uint16, lo, hi int64) int64 { return lo + (hi-lo)*int64(u)/65535 }

// KeeperPlan reads the computer's keeper plan from bytes 0-7.
func (s Seed) KeeperPlan() KeeperPlan {
	return KeeperPlan{
		Direction: u16(s[0:2]),
		Speed:     u16(s[2:4]),
		Jump:      u16(s[4:6]),
		Reaction:  u16(s[6:8]),
	}
}

// Mishit returns bytes 8-31.
func (s Seed) Mishit() [24]byte {
	var m [24]byte
	copy(m[:], s[8:32])
	return m
}

// ChainShot reads the computer's kick from bytes 0-7 (see Seed).
func (s Seed) ChainShot(c Config) ShotInput {
	halfW := c.GoalWidth/2 - ChainAimInset
	in := ShotInput{
		AimX:     span(u16(s[0:2]), -halfW, halfW),
		AimY:     span(u16(s[2:4]), ChainAimMinY, c.GoalHeight+ChainAimOverY),
		Power:    span(u16(s[4:6]), ChainPowerMin, 1000),
		ContactX: (int64(s[6]) - 128) * ChainContact / 128,
		ContactY: (int64(s[7]) - 128) * ChainContact / 128,
	}
	// Keep the contact inside this game's selectable disc.
	r2 := in.ContactX*in.ContactX + in.ContactY*in.ContactY
	if m := c.MaxContact; r2 > m*m {
		r := isqrt(r2)
		in.ContactX = in.ContactX * m / r
		in.ContactY = in.ContactY * m / r
	}
	return in
}

const hexDigits = "0123456789abcdef"

// Hex prints the seed as 64 hex characters.
func (s Seed) Hex() string { return toHex(s[:]) }

func toHex(b []byte) string {
	out := make([]byte, len(b)*2)
	for i, v := range b {
		out[2*i] = hexDigits[v>>4]
		out[2*i+1] = hexDigits[v&15]
	}
	return string(out)
}

// MishitHex prints a mishit seed as 48 hex characters.
func MishitHex(m [24]byte) string { return toHex(m[:]) }

// ParseMishitHex reads 48 hex characters.
func ParseMishitHex(s string) ([24]byte, bool) {
	var m [24]byte
	if len(s) != 48 {
		return m, false
	}
	for i := 0; i < 24; i++ {
		hi, ok1 := hexVal(s[2*i])
		lo, ok2 := hexVal(s[2*i+1])
		if !ok1 || !ok2 {
			return m, false
		}
		m[i] = hi<<4 | lo
	}
	return m, true
}

func hexVal(c byte) (byte, bool) {
	switch {
	case c >= '0' && c <= '9':
		return c - '0', true
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10, true
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}

// isqrt is the integer square root (floor).
func isqrt(n int64) int64 {
	if n <= 0 {
		return 0
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

package penalty

// Side is who takes a kick.
type Side uint8

const (
	SidePlayer Side = iota + 1
	SideChain
)

func (s Side) String() string {
	switch s {
	case SidePlayer:
		return "player"
	case SideChain:
		return "chain"
	}
	return "none"
}

// Other returns the opposing side.
func (s Side) Other() Side {
	if s == SidePlayer {
		return SideChain
	}
	return SidePlayer
}

// RegulationKicks is how many kicks each side takes before sudden death.
const RegulationKicks = 5

// Shootout is the score of a penalty shootout in which the player always
// kicks first in each round:
//
//   - each side takes RegulationKicks kicks, alternating;
//   - it ends early as soon as one side cannot be caught with the kicks the
//     other has left;
//   - level after regulation, it goes to sudden death: rounds of one kick
//     each, decided when one side scores and the other does not.
type Shootout struct {
	PlayerKicks int
	PlayerGoals int
	ChainKicks  int
	ChainGoals  int
}

// Next returns who kicks next (SidePlayer at the start of every round).
func (s Shootout) Next() Side {
	if s.PlayerKicks == s.ChainKicks {
		return SidePlayer
	}
	return SideChain
}

// Round is the 1-based number of the round in progress.
func (s Shootout) Round() int { return s.ChainKicks + 1 }

// SuddenDeath reports whether regulation is over.
func (s Shootout) SuddenDeath() bool { return s.ChainKicks >= RegulationKicks }

// Record adds a kick for side. It panics if side is out of turn or the
// shootout is already decided.
func (s *Shootout) Record(side Side, scored bool) {
	if s.Winner() != 0 {
		panic("penalty: the shootout is already decided")
	}
	if side != s.Next() {
		panic("penalty: " + side.String() + " is kicking out of turn")
	}
	g := 0
	if scored {
		g = 1
	}
	if side == SidePlayer {
		s.PlayerKicks++
		s.PlayerGoals += g
	} else {
		s.ChainKicks++
		s.ChainGoals += g
	}
}

// Winner returns the side that has won, or 0 while undecided.
func (s Shootout) Winner() Side {
	if s.PlayerKicks <= RegulationKicks && s.ChainKicks <= RegulationKicks {
		playerLeft := RegulationKicks - s.PlayerKicks
		chainLeft := RegulationKicks - s.ChainKicks
		if s.PlayerGoals > s.ChainGoals+chainLeft {
			return SidePlayer
		}
		if s.ChainGoals > s.PlayerGoals+playerLeft {
			return SideChain
		}
		return 0
	}
	// Sudden death: decided only once both have kicked in the round.
	if s.PlayerKicks == s.ChainKicks && s.PlayerGoals != s.ChainGoals {
		if s.PlayerGoals > s.ChainGoals {
			return SidePlayer
		}
		return SideChain
	}
	return 0
}

package penalty

// Outcome of a single kick.
type Outcome uint8

const (
	OutcomeGoal Outcome = iota + 1
	OutcomeSave
	OutcomeMiss
	OutcomePost
)

func (o Outcome) String() string {
	switch o {
	case OutcomeGoal:
		return "goal"
	case OutcomeSave:
		return "save"
	case OutcomeMiss:
		return "miss"
	case OutcomePost:
		return "woodwork"
	}
	return "unknown"
}

// Scored reports whether the kick counts as a goal.
func (o Outcome) Scored() bool { return o == OutcomeGoal }

// Result is what SimulateShot reports.
type Result struct {
	Outcome   Outcome
	X, Y      int64 // where the ball crosses (or would cross) the goal line, mm
	ArrivalMS int64 // time from contact to the line
	BallSpeed int64 // mm/s
	MishitX   int64 // contact error the mishit seed added, milli-radii
	MishitY   int64
	Keeper    Mode
}

// SimulateShot decides a kick from its ten inputs: the taker's six (five
// choices plus the mishit seed) and the keeper's four, played with the
// game's constants. It is a pure function: the same inputs give the same
// Result on every node, so anyone can re-run it to check a recorded kick.
//
// SUPERSEDED. This is the coarse integer model the realm used before the
// physics engine was ported (gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/physics/v0, which
// matches the browser game bit for bit and is what impl/v1 calls). It is kept
// so that kicks recorded under it can still be re-run.
func SimulateShot(shot ShotParams, plan KeeperPlan, c Config) Result {
	power := clampI(shot.Power, 0, 1000)

	// The boot lands off the chosen contact by a seeded, power-dependent error.
	sigma := c.FuzzBase + c.FuzzPower*power/1000
	mx := normalPermille(shot.Mishit, 0) * sigma / 1000
	my := normalPermille(shot.Mishit, 12) * sigma / 1000
	cx := clampI(shot.ContactX+mx, -800, 800)
	cy := clampI(shot.ContactY+my, -800, 800)

	// Glancing contact loses pace: about 1 - r²/2 of a centred strike.
	eff := 1000 - (cx*cx+cy*cy)*225/1000000
	speed := (c.BallMinSpeed + (c.BallMaxSpeed-c.BallMinSpeed)*power/1000) * eff / 1000
	t := Distance * 1000 / speed // ms to the line

	// Striking the right side sends the ball left and curls it further left;
	// hitting below centre lifts it, above centre dips it; gravity drops it.
	x := shot.AimX - cx*CurlPerMilliR/10
	drop := Gravity * t * t / 2 / 1000000
	y := shot.AimY - drop - cy*LiftPerMilliR/10
	if y < BallRadius {
		y = BallRadius
	}

	d := DecodePlan(plan, c)
	res := Result{X: x, Y: y, ArrivalMS: t, BallSpeed: speed, MishitX: mx, MishitY: my, Keeper: d.Mode}

	halfW := c.GoalWidth / 2
	ax := absI(x)
	inside := ax <= halfW-BallRadius && y <= c.GoalHeight-BallRadius
	clear := ax >= halfW+2*PostRadius+BallRadius || y >= c.GoalHeight+2*PostRadius+BallRadius
	switch {
	case clear:
		res.Outcome = OutcomeMiss
	case !inside:
		res.Outcome = OutcomePost
	case keeperCovers(d, c, shot, x, y, t, cx):
		res.Outcome = OutcomeSave
	default:
		res.Outcome = OutcomeGoal
	}
	return res
}

const (
	CurlPerMilliR = 45 // tenths of a mm of sideways travel per milli-radius of side contact
	LiftPerMilliR = 28 // tenths of a mm of lift per milli-radius below centre
	LaunchShare   = 20 // tenths of a mm of that sideways travel visible in the launch direction
)

// keeperCovers is the placeholder keeper: whether its body and hands reach
// (x, y) by the time the ball arrives (t ms after contact).
func keeperCovers(d Plan, c Config, shot ShotParams, x, y, t, cx int64) bool {
	s := c.KeeperScale
	reach := 900 * s / 1000 // hips to fingertips, sideways
	switch d.Mode {
	case ModeStar:
		// Spread wide in the middle of the goal, off the ground.
		return absI(x) <= 1100*s/1000 && y >= 450*s/1000
	case ModeRead:
		// Commits after seeing the ball: the slower the shot, the further it
		// gets. It reads the launch line, not the curl.
		commit := 160 + d.Reaction
		avail := t - commit
		if avail <= 0 {
			return absI(x) <= 350*s/1000 && y <= 1800*s/1000
		}
		predicted := shot.AimX - cx*LaunchShare/10
		cover := minI(reach+3500*avail/1000, c.GoalWidth/2+200)
		return absI(predicted) <= cover && absI(x-predicted) <= 450*s/1000
	}
	// Committed dive: the hips travel along the heading once the push-off
	// starts, the hands reach out from there, and the jump sets the height
	// band it covers.
	moving := t - d.Reaction - 60
	if moving < 0 {
		moving = 0
	}
	vx := d.Speed * cosPermille(d.Heading) / 1000
	hipX := clampI(vx*moving/1000, -2600*s/1000, 2600*s/1000)
	if absI(x) <= 300 && moving < 150 {
		return true // straight at a keeper that has barely left the spot
	}
	centre := 900 + d.Jump*450/1000
	band := 650 * s / 1000
	return absI(x-hipX) <= reach+150 && y >= centre-band && y <= centre+band
}

// normalPermille turns 12 bytes of a mishit seed into an approximately
// standard-normal value × 1000: six uint16 uniforms summed (Irwin-Hall,
// n = 6), centred and scaled.
func normalPermille(m [24]byte, offset int) int64 {
	var sum int64
	for i := 0; i < 6; i++ {
		sum += int64(u16(m[offset+2*i : offset+2*i+2]))
	}
	return (sum - 3*65535) * 1414 / 65535
}

package upgradeable

import "strings"

// Authority decides who may change what a [Proxy] points at.
//
// It is handed the identity of the caller -- the realm that crossed into the
// realm holding the Proxy. When a transaction is sent straight to that realm
// the caller is a user: pkgPath is empty and addr is the signer. When the
// call arrives through another realm, say a DAO executing a proposal, pkgPath
// names that realm and addr is the realm's own address.
//
// Both halves are passed because the two authorization styles on gno.land
// read different ones: an owner check compares addresses, a governance check
// compares realm paths. An implementation must read the half it means and
// ignore the other. In particular an empty pkgPath is not a realm -- it is
// every user call -- so a path check must reject it explicitly.
type Authority interface {
	Authorized(addr address, pkgPath string) bool
	String() string
}

// AddrAuthority authorizes exactly one address: the signer of a direct call,
// or a realm acting at that address.
type AddrAuthority struct {
	addr address
}

// NewAddrAuthority returns an Authority holding addr.
func NewAddrAuthority(addr address) *AddrAuthority {
	if !addr.IsValid() {
		panic(ErrBadAddress)
	}
	return &AddrAuthority{addr: addr}
}

func (a *AddrAuthority) Authorized(addr address, _ string) bool {
	return a != nil && addr.IsValid() && addr == a.addr
}

// Address returns the authorized address.
func (a *AddrAuthority) Address() address {
	if a == nil {
		return ""
	}
	return a.addr
}

func (a *AddrAuthority) String() string {
	if a == nil {
		return "addr:<nil>"
	}
	return "addr:" + a.addr.String()
}

// RealmAuthority authorizes a fixed set of realm paths, the shape r/gov/dao
// uses: a governance realm executes the upgrade, and the proxy recognizes it
// by the path it was deployed at rather than by an address.
//
// More than one path is allowed so that authority can be moved without a gap:
// list both the old and the new governance realm, let the new one take over,
// then narrow the list.
type RealmAuthority struct {
	paths []string
}

// NewRealmAuthority returns an Authority holding paths. It panics on an empty
// list rather than authorizing nobody, and on a blank or padded entry rather
// than storing one that can never match a caller -- or, for a blank one,
// matches every user call.
func NewRealmAuthority(paths ...string) *RealmAuthority {
	if len(paths) == 0 {
		panic(ErrNoAuthority)
	}
	out := make([]string, 0, len(paths))
	for _, p := range paths {
		if p == "" || p != strings.TrimSpace(p) {
			panic(ErrBadRealmPath)
		}
		out = append(out, p)
	}
	return &RealmAuthority{paths: out}
}

func (a *RealmAuthority) Authorized(_ address, pkgPath string) bool {
	if a == nil || pkgPath == "" {
		return false
	}
	for _, p := range a.paths {
		if p == pkgPath {
			return true
		}
	}
	return false
}

// Paths returns a copy of the authorized realm paths.
func (a *RealmAuthority) Paths() []string {
	if a == nil {
		return nil
	}
	dup := make([]string, len(a.paths))
	copy(dup, a.paths)
	return dup
}

func (a *RealmAuthority) String() string {
	if a == nil {
		return "realms:<nil>"
	}
	return "realms:" + strings.Join(a.paths, ",")
}

// AnyOf authorizes a caller that any of its members authorizes. It is the
// handover shape for the common case: hold an address authority while you are
// still deploying, add the governance realm, drop the address later.
type AnyOf struct {
	auths []Authority
}

// NewAnyOf returns an Authority satisfied by any of auths. It panics on an
// empty list or a nil member, both of which would silently weaken or void
// the check.
func NewAnyOf(auths ...Authority) *AnyOf {
	if len(auths) == 0 {
		panic(ErrNoAuthority)
	}
	out := make([]Authority, 0, len(auths))
	for _, a := range auths {
		if a == nil {
			panic(ErrNoAuthority)
		}
		out = append(out, a)
	}
	return &AnyOf{auths: out}
}

func (a *AnyOf) Authorized(addr address, pkgPath string) bool {
	if a == nil {
		return false
	}
	for _, sub := range a.auths {
		if sub.Authorized(addr, pkgPath) {
			return true
		}
	}
	return false
}

func (a *AnyOf) String() string {
	if a == nil {
		return "anyOf:<nil>"
	}
	parts := make([]string, 0, len(a.auths))
	for _, sub := range a.auths {
		parts = append(parts, sub.String())
	}
	return "anyOf(" + strings.Join(parts, " ") + ")"
}

package upgradeable

import "errors"

var (
	// ErrNoAuthority is raised when a Proxy is built, or handed, a nil
	// authority. There is no "nobody" authority: to end upgradeability,
	// Freeze it.
	ErrNoAuthority = errors.New("upgradeable: an authority is required")

	// ErrUnauthorized is raised when the caller is not the authority.
	ErrUnauthorized = errors.New("upgradeable: caller is not the authority")

	// ErrStaleRealm is raised when the threaded realm value is not the
	// caller's live cur -- a stashed or replayed capture.
	ErrStaleRealm = errors.New("upgradeable: realm value is not the caller's live cur")

	// ErrFrozen is raised by every mutating method once Freeze has run.
	ErrFrozen = errors.New("upgradeable: proxy is frozen")

	// ErrNoImpl is raised when the proxy is asked for an implementation it
	// does not have yet.
	ErrNoImpl = errors.New("upgradeable: no implementation is live")

	// ErrNotNested is raised when a candidate registers from a realm that is
	// not under the proxy realm's own path. See New and NewOpen.
	ErrNotNested = errors.New("upgradeable: candidate realm is not nested under this one")

	// ErrNotARealm is raised when a candidate registers from a user call
	// rather than from a deployed realm, so there is no path to record.
	ErrNotARealm = errors.New("upgradeable: only a deployed realm can register a candidate")

	// ErrNilImpl is raised when the registered implementation is nil.
	ErrNilImpl = errors.New("upgradeable: implementation is nil")

	// ErrUnknownPath is raised when accepting or withdrawing a path that has
	// no candidate registered against it.
	ErrUnknownPath = errors.New("upgradeable: no candidate registered at that path")

	// ErrNoHistory is raised by Rollback when nothing has been replaced yet.
	ErrNoHistory = errors.New("upgradeable: no previous release to roll back to")

	// ErrBadAddress is raised when an authority is built from an invalid
	// address.
	ErrBadAddress = errors.New("upgradeable: invalid address")

	// ErrBadRealmPath is raised when an authority is built from a realm path
	// that is blank or carries surrounding whitespace. Both are silent
	// lockouts: a blank entry matches every user call, and a padded one
	// matches no caller at all.
	ErrBadRealmPath = errors.New("upgradeable: authority realm paths must be non-blank and unpadded")
)

// Package upgradeable lets a realm at a permanent path serve behavior that
// can change.
//
// A gno.land package path is immutable. The VM keeper refuses MsgAddPackage
// at a path that already holds a package, and the one exception -- private
// = true in gnomod.toml -- buys redeployability by giving up importability,
// and starts the realm's globals over from nothing besides. So a realm other
// people import cannot have its code replaced. What it can do is decide at
// call time which object it calls, and that object can live in a realm
// deployed years later. There is no delegatecall here and imports resolve
// statically: the indirection is an ordinary interface value, handed over by
// the realm that implements it.
//
// [Proxy] is the bookkeeping for that. It holds the one live implementation,
// the candidates waiting to replace it, and the ones it used to be, with an
// [Authority] deciding who may move between them. What it deliberately does
// not hold is your state. State belongs in the realm at the permanent path,
// or in a realm of its own, so that replacing an implementation does not
// touch it -- see the counter example under r/ for both halves.
//
// This is a p/ package on purpose. Pure packages can never be redeployed, so
// the rules below cannot be swapped out from under the realm that relies on
// them, which is exactly the property an upgrade mechanism has to have.
//
// # Threading cur
//
// Every authority-sensitive method takes (_ int, rlm realm): the caller
// threads its own cur as data instead of crossing into this package. The
// leading int keeps rlm out of first position, where it would declare a
// crossing function. rlm.Previous() is then the realm that crossed into the
// caller -- the user sending the transaction, the governance realm executing
// a proposal, or the implementation realm registering itself -- and
// rlm.IsCurrent() is what makes that unforgeable: a realm value cannot be
// persisted, and a stale capture fails the check.
package upgradeable

import (
	"chain"
	"chain/runtime"
	"strings"
)

// Event types emitted on every state change, so an indexer can reconstruct
// which code served which block without replaying the realm.
const (
	ProposeEvent   = "UpgradeProposed"
	WithdrawEvent  = "UpgradeWithdrawn"
	AcceptEvent    = "UpgradeAccepted"
	RollbackEvent  = "UpgradeRolledBack"
	ForgetEvent    = "UpgradeHistoryDropped"
	ExtendEvent    = "UpgradeExtensionAdded"
	UnextendEvent  = "UpgradeExtensionDropped"
	FreezeEvent    = "UpgradeFrozen"
	AuthorityEvent = "UpgradeAuthorityTransferred"
)

// Release is one implementation: the object, and the realm that authored it.
//
// PkgPath is read off the crossing frame at registration, never taken as an
// argument, so it names the realm the code actually lives at. That is what
// makes it worth reviewing before an upgrade is accepted, and what lets a
// state realm recognize the live implementation later.
//
// Release is returned by value. The proxy's own copy stays unreachable from
// outside, so a reader cannot rewrite history.
type Release struct {
	pkgPath string
	impl    any
	height  int64
}

// PkgPath returns the realm path the implementation was registered from.
func (r Release) PkgPath() string { return r.pkgPath }

// Impl returns the implementation object.
func (r Release) Impl() any { return r.impl }

// Height returns the block height at which the implementation registered.
func (r Release) Height() int64 { return r.height }

// IsZero reports whether r is the zero Release, which is what accessors
// return alongside a false ok.
func (r Release) IsZero() bool { return r.pkgPath == "" }

// Proxy holds the live implementation and the bookkeeping around replacing
// it. Keep one as a realm-level variable; it persists with the realm.
type Proxy struct {
	auth    Authority
	live    *Release
	pending []*Release // kept sorted by pkgPath
	past    []*Release
	exts    []string // kept sorted; realms allowed to act as this one
	frozen  bool
	nested  bool
}

// New returns a Proxy whose candidates must register from a realm nested
// under the realm holding it: gno.land/r/you/app/impl/v1 under
// gno.land/r/you/app. Deploying under that prefix needs your namespace, so
// the pending set cannot be filled by strangers.
//
// It panics on a nil authority. Upgradeability with no authority is not
// "nobody can upgrade" -- to reach that, Freeze.
func New(auth Authority) *Proxy {
	return newProxy(auth, true)
}

// NewOpen is New without the nesting rule: any deployed realm may register a
// candidate and the authority alone decides. Use it when implementations
// come from outside your namespace. The cost is that anyone can add entries
// to the pending set, which lives in your realm's storage; Withdraw clears
// them.
func NewOpen(auth Authority) *Proxy {
	return newProxy(auth, false)
}

func newProxy(auth Authority, nested bool) *Proxy {
	if auth == nil {
		panic(ErrNoAuthority)
	}
	return &Proxy{
		auth:   auth,
		nested: nested,
	}
}

// Impl returns the live implementation, and panics with ErrNoImpl if nothing
// has been accepted yet. Realms call this on every request, so the panic is
// the honest answer: a proxy with no implementation has no behavior to serve.
func (p *Proxy) Impl() any {
	if p.live == nil {
		panic(ErrNoImpl)
	}
	return p.live.impl
}

// TryImpl returns the live implementation and whether there is one, for
// callers that would rather render an empty page than fail the transaction.
func (p *Proxy) TryImpl() (any, bool) {
	if p.live == nil {
		return nil, false
	}
	return p.live.impl, true
}

// Live returns the live release.
func (p *Proxy) Live() (Release, bool) {
	if p.live == nil {
		return Release{}, false
	}
	return *p.live, true
}

// LivePath returns the realm path of the live implementation, or "" if there
// is none. A state realm that wants to grant write access to whichever
// implementation is current compares its caller against this.
func (p *Proxy) LivePath() string {
	if p.live == nil {
		return ""
	}
	return p.live.pkgPath
}

// Pending returns the registered candidates, ordered by path.
func (p *Proxy) Pending() []Release {
	out := make([]Release, 0, len(p.pending))
	for _, r := range p.pending {
		out = append(out, *r)
	}
	return out
}

// History returns the releases this proxy has already served, oldest first.
// It excludes the live one, and Forget empties it.
func (p *Proxy) History() []Release {
	out := make([]Release, 0, len(p.past))
	for _, r := range p.past {
		out = append(out, *r)
	}
	return out
}

// Frozen reports whether upgradeability has ended.
func (p *Proxy) Frozen() bool { return p.frozen }

// Authority returns the current authority.
func (p *Proxy) Authority() Authority { return p.auth }

// Extensions returns the realm paths allowed to act as the realm holding this
// proxy, in sorted order.
//
// A realm path is fixed, so the exported functions of the realm holding this
// proxy can never grow. What can grow is the set of OTHER realms permitted to
// run against its state: a realm deployed later declares an interface of its
// own, asserts the live implementation to it, and calls through. That is how
// an application adds an entry point it did not ship with. See the
// "extending a frozen API" pattern in the repository docs.
//
// The state accessor in the realm holding this proxy is what consults this --
// nothing here reaches into your state on its own.
func (p *Proxy) Extensions() []string {
	dup := make([]string, len(p.exts))
	copy(dup, p.exts)
	return dup
}

// IsExtension reports whether pkgPath may act as the realm holding this proxy.
// Call it from the state accessor, alongside the check for the realm's own
// path.
func (p *Proxy) IsExtension(pkgPath string) bool {
	if pkgPath == "" {
		return false // a user call is not a realm
	}
	for _, e := range p.exts {
		if e == pkgPath {
			return true
		}
	}
	return false
}

// AddExtension permits pkgPath to act as the realm holding this proxy.
//
// This grants the authority no power it did not have. An authority that can
// Accept an arbitrary implementation can already run arbitrary code against
// the state; naming a second realm that may do the same widens what is
// reachable, not who decides. It does widen the surface a reviewer has to
// read, which is why Extensions is public and Render should show it.
//
// Caller: the authority.
func (p *Proxy) AddExtension(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if pkgPath == "" || pkgPath != strings.TrimSpace(pkgPath) {
		panic(ErrBadRealmPath)
	}
	if p.IsExtension(pkgPath) {
		return
	}
	at := len(p.exts)
	for i, e := range p.exts {
		if pkgPath < e {
			at = i
			break
		}
	}
	p.exts = append(p.exts, "")
	copy(p.exts[at+1:], p.exts[at:])
	p.exts[at] = pkgPath
	chain.Emit(ExtendEvent, "realm", pkgPath)
}

// DropExtension revokes pkgPath. The extension realm stays deployed and keeps
// answering calls; it just stops being able to reach the state, so whatever it
// exposed starts panicking rather than disappearing.
//
// Caller: the authority.
func (p *Proxy) DropExtension(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	for i, e := range p.exts {
		if e == pkgPath {
			p.exts = append(p.exts[:i], p.exts[i+1:]...)
			chain.Emit(UnextendEvent, "realm", pkgPath)
			return
		}
	}
	panic(ErrUnknownPath)
}

// AssertAuthorized panics unless rlm's caller is the authority. It exists for
// wrappers that do work of their own before delegating -- a schema check
// before Accept, say -- so that an unauthorized caller is refused for the
// right reason rather than tripping over the wrapper's own validation first.
func (p *Proxy) AssertAuthorized(_ int, rlm realm) { p.assertAuthorized(0, rlm) }

// Propose registers impl as a candidate, filed under the path of the realm
// that is calling.
//
// That path comes off the crossing frame rather than from an argument, and
// that is the point of the whole mechanism: a candidate cannot claim to have
// been authored by a path it does not occupy. Whoever accepts it is
// therefore accepting code they can go and read at that path, and a state
// realm that gates writes on LivePath is gating on the same authenticated
// string.
//
// The implementation realm calls this from its own init, so deploying the
// new version is what nominates it. Nothing is served until the authority
// accepts. Re-registering from the same realm replaces that candidate, which
// is the retry path after a failed deployment.
func (p *Proxy) Propose(_ int, rlm realm, impl any) {
	p.assertMutable()
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	if impl == nil {
		panic(ErrNilImpl)
	}

	prev := rlm.Previous()
	from := prev.PkgPath()
	if from == "" || prev.IsEphemeral() {
		// A user call has no path to record at all. An ephemeral one does
		// have a path -- `gnokey maketx run` executes in /e/<addr>/run --
		// but it does not outlive the transaction, so filing a candidate
		// under it records a path that will never hold the code it claims.
		// The emptiness check alone does not catch that one.
		panic(ErrNotARealm)
	}
	if p.nested && !isNested(rlm.PkgPath(), from) {
		panic(ErrNotNested)
	}

	p.setPending(&Release{
		pkgPath: from,
		impl:    impl,
		height:  runtime.ChainHeight(),
	})
	chain.Emit(ProposeEvent, "impl", from)
}

// Withdraw drops a candidate. The authority may drop any; a realm may always
// drop its own, which is how a superseded candidate stops costing storage
// without the authority having to act.
func (p *Proxy) Withdraw(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	if rlm.Previous().PkgPath() != pkgPath {
		p.assertAuthorized(0, rlm)
	}
	if !p.removePending(pkgPath) {
		panic(ErrUnknownPath)
	}
	chain.Emit(WithdrawEvent, "impl", pkgPath)
}

// Accept makes the candidate at pkgPath the live implementation, and files
// the one it replaces in History.
//
// This is the upgrade. It is a separate transaction from the deployment that
// registered the candidate, by a separate principal, which is what gives the
// authority something reviewable to act on -- the same two-phase shape
// gno.land itself uses when a chain parks a submission until an approver
// enables it.
func (p *Proxy) Accept(_ int, rlm realm, pkgPath string) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)

	i := p.findPending(pkgPath)
	if i < 0 {
		panic(ErrUnknownPath)
	}
	rel := p.pending[i]
	p.removePending(pkgPath)

	from := ""
	if p.live != nil {
		from = p.live.pkgPath
		p.past = append(p.past, p.live)
	}
	p.live = rel
	chain.Emit(AcceptEvent, "impl", pkgPath, "replaced", from)
}

// Rollback puts the previous release back in front, and returns the one it
// displaces to the pending set so a fixed version can be re-accepted without
// redeploying it.
//
// This is why History is kept: the release objects stay reachable, and
// reachable is the only form of "still deployed" that matters here. It costs
// storage, which is what Forget is for once a version has proven itself.
func (p *Proxy) Rollback(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)

	n := len(p.past)
	if n == 0 {
		panic(ErrNoHistory)
	}
	prev := p.past[n-1]
	p.past = p.past[:n-1]

	from := ""
	if p.live != nil {
		from = p.live.pkgPath
		p.setPending(p.live)
	}
	p.live = prev
	chain.Emit(RollbackEvent, "impl", prev.pkgPath, "replaced", from)
}

// Forget drops the history, releasing the old implementations. Rollback
// stops working -- there is nothing to roll back to -- so this is the "the
// current version has proven itself" move, not routine cleanup.
func (p *Proxy) Forget(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	dropped := len(p.past)
	p.past = nil
	chain.Emit(ForgetEvent, "dropped", itoa(dropped))
}

// TransferAuthority hands the power to upgrade to auth. It panics on nil:
// there is no way to leave a proxy upgradeable by nobody, because that state
// is indistinguishable from a mistake. Freeze says it on purpose.
func (p *Proxy) TransferAuthority(_ int, rlm realm, auth Authority) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if auth == nil {
		panic(ErrNoAuthority)
	}
	old := p.auth.String()
	p.auth = auth
	chain.Emit(AuthorityEvent, "from", old, "to", auth.String())
}

// Freeze ends upgradeability for good. The live implementation keeps serving
// and nothing can replace it: no unfreeze, by design, because a proxy that
// can be thawed has not actually given anything up. This is how a realm
// graduates from "we are still fixing it" to something other realms can
// build on -- an interrealm contract is only as trustworthy as the least
// mutable realm behind it.
//
// It refuses to freeze with nothing live, which would leave the realm
// permanently unable to answer a call.
//
// Freezing finalizes the extension set. Whatever is registered survives (the
// frozen implementation may depend on it), but afterwards nothing can be added
// and -- because Drop is a mutation too -- nothing can be dropped. So a
// registered extension keeps its access to the realm's state for good. Review
// the extensions before you freeze; you cannot revoke one after.
func (p *Proxy) Freeze(_ int, rlm realm) {
	p.assertMutable()
	p.assertAuthorized(0, rlm)
	if p.live == nil {
		panic(ErrNoImpl)
	}
	p.frozen = true
	p.pending = nil
	p.past = nil
	// Extensions are deliberately kept. They are reachable code that the
	// frozen implementation may depend on, and dropping them here would
	// break entry points that were working a block ago -- a freeze should
	// fix the realm's behavior, not change it.
	chain.Emit(FreezeEvent, "impl", p.live.pkgPath)
}

// isNested reports whether child is parent, or sits under it. The trailing
// separators are what keep gno.land/r/you/appliance from counting as nested
// under gno.land/r/you/app.
func isNested(parent, child string) bool {
	return strings.HasPrefix(child+"/", parent+"/")
}

// findPending returns the index of the candidate at pkgPath, or -1.
func (p *Proxy) findPending(pkgPath string) int {
	for i, r := range p.pending {
		if r.pkgPath == pkgPath {
			return i
		}
	}
	return -1
}

// setPending inserts rel, or replaces the candidate already at its path.
// The slice is kept sorted so Pending and any Render built on it read the
// same way on every node.
func (p *Proxy) setPending(rel *Release) {
	if i := p.findPending(rel.pkgPath); i >= 0 {
		p.pending[i] = rel
		return
	}
	at := len(p.pending)
	for i, r := range p.pending {
		if rel.pkgPath < r.pkgPath {
			at = i
			break
		}
	}
	p.pending = append(p.pending, nil)
	copy(p.pending[at+1:], p.pending[at:])
	p.pending[at] = rel
}

// removePending drops the candidate at pkgPath, reporting whether one was
// there.
func (p *Proxy) removePending(pkgPath string) bool {
	i := p.findPending(pkgPath)
	if i < 0 {
		return false
	}
	p.pending = append(p.pending[:i], p.pending[i+1:]...)
	return true
}

func (p *Proxy) assertMutable() {
	if p.frozen {
		panic(ErrFrozen)
	}
}

func (p *Proxy) assertAuthorized(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
	caller := rlm.Previous()
	if !p.auth.Authorized(caller.Address(), caller.PkgPath()) {
		panic(ErrUnauthorized)
	}
}

// itoa avoids pulling ufmt in for one event attribute.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// Package shootout holds the state types of gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shots:
// games, challengers' sessions and their kicks.
//
// They live in a package rather than in the realm because gno only lets a
// realm's own code allocate the types that realm declares, and the game's
// rules engine runs in a separate, upgradeable implementation realm. Declared
// here, both realms can build and read them, and like the realm's storage
// they never change once deployed.
package shootout

import "gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/v0"

// GameStatus is where a game is in its life.
type GameStatus uint8

const (
	GameOpen      GameStatus = iota + 1 // waiting for a challenger
	GamePlaying                         // a challenger is playing a shootout
	GameWon                             // a challenger won the pot; closed
	GameCancelled                       // the creator withdrew it before anyone played; closed
)

func (s GameStatus) String() string {
	switch s {
	case GameOpen:
		return "open"
	case GamePlaying:
		return "playing"
	case GameWon:
		return "won"
	case GameCancelled:
		return "cancelled"
	}
	return "unknown"
}

// Game is a pot and the constants it is played for.
type Game struct {
	ID            uint64
	Creator       address
	Config        penalty.Config
	EntryFee      int64 // ugnot a challenger pays into the pot to play
	TimeoutBlocks int64 // a challenger idle this long may be forfeited by anyone
	Pot           int64 // ugnot
	Status        GameStatus
	Sessions      int // challengers so far; while playing, the live session is number Sessions
	Winner        address
	CreatedHeight int64
	ClosedHeight  int64
}

// SessionStatus is how a challenger's shootout stands.
type SessionStatus uint8

const (
	SessionPlaying SessionStatus = iota + 1
	SessionWon
	SessionLost
	SessionForfeited
)

func (s SessionStatus) String() string {
	switch s {
	case SessionPlaying:
		return "playing"
	case SessionWon:
		return "won"
	case SessionLost:
		return "lost"
	case SessionForfeited:
		return "forfeited"
	}
	return "unknown"
}

// Kick is one kick of a shootout, with everything needed to re-run it:
// penalty.SimulateShot(Shot, Plan, game.Config) == Result. Seed is the
// 32 bytes that completed it, derived from the block it was played in.
type Kick struct {
	Round  int
	Kicker penalty.Side
	Shot   penalty.ShotParams
	Plan   penalty.KeeperPlan
	Seed   penalty.Seed
	Result penalty.Result
	Height int64 // block the kick was played in
	Time   int64 // its block time, unix nanoseconds (the seed's source)
}

// Session is one challenger's shootout against the chain.
type Session struct {
	GameID           uint64
	No               int
	Player           address
	Paid             int64
	Score            penalty.Shootout
	Kicks            []Kick
	Status           SessionStatus
	JoinHeight       int64
	LastActionHeight int64
	EndHeight        int64
}

// Next says what the session is waiting for: "shoot", "keep", or "none" once
// it is over.
func (s Session) Next() string {
	if s.Status != SessionPlaying {
		return "none"
	}
	if s.Score.Next() == penalty.SidePlayer {
		return "shoot"
	}
	return "keep"
}

