	pushT      float64
	groundT    float64
	pos, vel   vec
	lean       lean2
	arms       armPair
	launchVel  vec
	leanTarget lean2
	armsTarget armPair
	plant      plant
	plantUntil float64
	commits    []Commit
	holding    bool
	read       pred    // its latest read of where the ball will cross
	nextRead   int     // the step of its next read
	seen       ball    // the ball at a read not worked out yet (see keeperStep)
	seenZ      float64 // and the keeper's z, and the time, at that read
	seenT      float64
	pending    bool
	clr        float64
	clrS, clrC float64 // the lean clr was computed for
	clrOK      bool
}

type pred struct {
	ok   bool
	x, y float64
	tau  float64
}

func (e *engine) keeperInit(m misread) keeper {
	return keeper{
		mis:        m,
		phase:      phaseReady,
		pos:        vec{0, e.standHipY, goalZ + kLineOffset},
		lean:       lean2{0, 1},
		arms:       armsReady,
		leanTarget: lean2{0, 1},
		armsTarget: armsReady,
		nextRead:   1,
	}
}

func margin(kind int) float64 {
	switch kind {
	case kindGlove:
		return kMarginGlove
	case kindArm:
		return kMarginArm
	case kindTorso:
		return kMarginTorso
	case kindLeg:
		return kMarginLeg
	}
	return kMarginHead
}

// Fixed offsets of the body points, already scaled: what the browser's w()
// computes as x *= S, y *= S for each constant point, per side.
type sideK struct {
	side                        float64
	sx                          float64 // shoulder x, unscaled
	legX, legY, footX, footY    float64
	torX, torAY, torBY          float64
	armAX, armAY                float64
	legR, torR, armR, gloveR    float64
	legH, torH, armH, gloveH    float64
	legPart, armPart, glovePart int
}

func (e *engine) initBody() {
	S := e.scale
	zero := 0.0
	for i, side := range [2]float64{-1, 1} {
		k := sideK{side: side, sx: kShoulderX * side}
		k.legX, k.legY = 0.11*side*S, zero*S
		k.footX, k.footY = 0.15*side*S, -0.85*S
		k.torX, k.torAY, k.torBY = 0.09*side*S, 0.05*S, 0.46*S
		k.armAX, k.armAY = k.sx*S, kShoulderY*S
		k.legR, k.torR, k.armR, k.gloveR = 0.08*S, 0.14*S, 0.055*S, kGloveR
		k.legH, k.torH, k.armH, k.gloveH = k.legR+kMarginLeg, k.torR+kMarginTorso, k.armR+kMarginArm, k.gloveR+kMarginGlove
		if side < 0 {
			k.legPart, k.armPart, k.glovePart = partLeftLeg, partLeftArm, partLeftGlove
		} else {
			k.legPart, k.armPart, k.glovePart = partRightLeg, partRightArm, partRightGlove
		}
		e.body[i] = k
	}
	e.headX, e.headY = zero*S, 0.72*S
	e.headR = 0.12 * S
	e.headH = e.headR + kMarginHead
	e.zeroZ = zero * S
}

// wpt is the browser's w() for a point already scaled: X = x*S, Y = y*S,
// Z = z*S.
func wpt(pos vec, ln lean2, X, Y, Z float64) vec {
	return vec{pos.x + X*ln.c + Y*ln.s, pos.y - X*ln.s + Y*ln.c, pos.z + Z}
}

// initCaps sets what never changes in the keeper's collision shapes: radii,
// kinds and parts, in the browser's order (left leg, body, left arm, left
// glove, the same on the right, head).
func (e *engine) initCaps(cs *caps) {
	for i := 0; i < 2; i++ {
		k := &e.body[i]
		j := 4 * i
		cs[j] = capsule{r: k.legR, hit: k.legH, kind: kindLeg, part: k.legPart}
		cs[j+1] = capsule{r: k.torR, hit: k.torH, kind: kindTorso, part: partBody}
		cs[j+2] = capsule{r: k.armR, hit: k.armH, kind: kindArm, part: k.armPart}
		cs[j+3] = capsule{r: k.gloveR, hit: k.gloveH, kind: kindGlove, part: k.glovePart}
	}
	cs[8] = capsule{r: e.headR, hit: e.headH, kind: kindHead, part: partHead}
}

// capsulesInto sets the end points of the shapes in cs (see initCaps) for a
// pose: the browser's keeperCapsules, each point wpt written out.
func (e *engine) capsulesInto(cs *caps, ps *pose) {
	S := e.scale
	px, py, pz := ps.pos.x, ps.pos.y, ps.pos.z
	s, c := ps.lean.s, ps.lean.c
	z0 := pz + e.zeroZ
	pl := &ps.plant
	for i := 0; i < 2; i++ {
		k := &e.body[i]
		arm := &ps.arms.r
		if k.side < 0 {
			arm = &ps.arms.l
		}
		ax, ay, az := arm.x, arm.y, arm.z
		j := 4 * i
		cp := &cs[j]
		X, Y := k.legX, k.legY
		cp.a = vec{px + X*c + Y*s, py - X*s + Y*c, z0}
		if pl.on && pl.side == k.side {
			cp.b = vec{pl.x, pl.y, pl.z}
		} else {
			X, Y = k.footX, k.footY
			cp.b = vec{px + X*c + Y*s, py - X*s + Y*c, z0}
		}
		cp = &cs[j+1]
		X, Y = k.torX, k.torAY
		cp.a = vec{px + X*c + Y*s, py - X*s + Y*c, z0}
		Y = k.torBY
		cp.b = vec{px + X*c + Y*s, py - X*s + Y*c, z0}
		cp = &cs[j+2]
		X, Y = k.armAX, k.armAY
		cp.a = vec{px + X*c + Y*s, py - X*s + Y*c, z0}
		X, Y = (k.sx+ax*kArmLen)*S, (kShoulderY+ay*kArmLen)*S
		cp.b = vec{px + X*c + Y*s, py - X*s + Y*c, pz + az*kArmLen*S}
		cp = &cs[j+3]
		X, Y = (k.sx+ax*kGloveReach)*S, (kShoulderY+ay*kGloveReach)*S
		g := vec{px + X*c + Y*s, py - X*s + Y*c, pz + az*kGloveReach*S}
		cp.a, cp.b = g, g
	}
	X, Y := e.headX, e.headY
	h := vec{px + X*c + Y*s, py - X*s + Y*c, z0}
	cs[8].a, cs[8].b = h, h
}

func (e *engine) keeperCaps(k *keeper) caps {
	var cs caps
	e.initCaps(&cs)
	ps := poseOf(k)
	e.capsulesInto(&cs, &ps)
	return cs
}

// clearance is keeperClearance: the hip height at which the lowest of the
// legs, torso and head touches the ground (the browser builds every shape at
// the origin; only these heights matter).
func (e *engine) clearance(k *keeper) float64 {
	s, c := k.lean.s, k.lean.c
	// The browser's Math.min over these heights, in its order, signed zeros
	// included: jsMin only when two are equal.
	l := &e.body[0]
	r := &e.body[1]
	m := 0 - l.legX*s + l.legY*c - l.legR
	if v := 0 - l.footX*s + l.footY*c - l.legR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - l.torX*s + l.torAY*c - l.torR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - l.torX*s + l.torBY*c - l.torR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - r.legX*s + r.legY*c - r.legR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - r.footX*s + r.footY*c - r.legR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - r.torX*s + r.torAY*c - r.torR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - r.torX*s + r.torBY*c - r.torR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	if v := 0 - e.headX*s + e.headY*c - e.headR; v < m {
		m = v
	} else if v == m {
		m = jsMin(m, v)
	}
	return -m
}

func (e *engine) armsAboveGround(k *keeper) {
	s, c := k.lean.s, k.lean.c
	sy := e.shY
	reach := e.gloveReachS
	py := k.pos.y
	syc := sy * c
	// Left arm, then right, as the browser's loop over the sides.
	shoulderY := py - e.shXL*s + syc
	minDy := (kGloveR - shoulderY) / reach
	if minDy < 1 {
		arm := &k.arms.l
		if -arm.x*s+arm.y*c < minDy {
			liftArm(arm, minDy, s, c)
		}
	}
	shoulderY = py - e.shXR*s + syc
	minDy = (kGloveR - shoulderY) / reach
	if minDy < 1 {
		arm := &k.arms.r
		if -arm.x*s+arm.y*c < minDy {
			liftArm(arm, minDy, s, c)
		}
	}
}

// liftArm raises an arm (body frame) whose hand would be below the ground
// to world height minDy, keeping its direction across.
func liftArm(arm *vec, minDy, s, c float64) {
	wx := arm.x*c + arm.y*s
	h0 := fsqrt(wx*wx + arm.z*arm.z)
	h := fsqrt(1 - minDy*minDy)
	nx, nz := h, 0.0
	if h0 > 0 {
		nx = (wx * h) / h0
		nz = (arm.z * h) / h0
	}
	*arm = vec{nx*c - minDy*s, nx*s + minDy*c, nz}
}

// pose is what the keeper's shapes are built from.
type pose struct {
	pos   vec
	lean  lean2
	arms  armPair
	plant plant
}

func poseOf(k *keeper) pose { return pose{k.pos, k.lean, k.arms, k.plant} }

// blocks is the keeper's movement at 50 Hz: blocks of keeperBlock steps,
// each one keeper step of that length taken at the block's start, from pose
// A (the block's start) to pose B (its end). A block in which its plan
// commits is a single millisecond instead, so the reaction time keeps 1 ms
// precision. Within a block the shapes the ball meets are interpolated
// between A's and B's, one per millisecond, at the block's constant velocity.
type blocks struct {
	s0, n     int
	ia        int // pose[ia] is pose A (the block's start), pose[1-ia] pose B
	pose      [2]pose
	cbuf      [2]caps // the shapes of each pose
	ok        [2]bool // whether cbuf holds them
	vel       [nCaps][2]vec
	velOK     [nCaps]bool
	box       [nCaps][6]float64 // lo/hi x, y, z of each part's end points over the block
	boxOK     [nCaps]bool
	lastBox   [nCaps][6]float64 // the same for pose B alone (the block's last step)
	lastBoxOK [nCaps]bool
	body      [6]float64 // every part over the block, widened by maxReach
	bodyOK    bool
	cand      [nCaps]bool // parts that can reach a ball within candR of candP this block
	candP     vec
	candOK    bool
}

func blockLen(k *keeper, pl *Plan, step int) int {
	if k.phase != phaseReady {
		return keeperBlock
	}
	if k.holding {
		return keeperBlock
	}
	if pl.commitTime() <= float64(step+keeperBlock-1)*simDT {
		return 1
	}
	return keeperBlock
}

func (e *engine) keeperBlock(k *keeper, pl *Plan, step int, b *ball, kb *blocks) {
	kb.s0 = step
	kb.n = blockLen(k, pl, step)
	kb.ia = 1 - kb.ia // B becomes A, with its shapes
	kb.velOK = [nCaps]bool{}
	kb.boxOK = [nCaps]bool{}
	kb.lastBoxOK = [nCaps]bool{}
	kb.bodyOK = false
	kb.candOK = false
	end := step + kb.n - 1
	e.keeperStep(k, pl, end, float64(end)*simDT, float64(kb.n)*simDT, b)
	kb.pose[1-kb.ia] = poseOf(k)
	kb.ok[1-kb.ia] = false
}

func (e *engine) blockCapsA(kb *blocks) *caps {
	i := kb.ia
	if !kb.ok[i] {
		e.capsulesInto(&kb.cbuf[i], &kb.pose[i])
		kb.ok[i] = true
	}
	return &kb.cbuf[i]
}

func (e *engine) blockCapsB(kb *blocks) *caps {
	i := 1 - kb.ia
	if !kb.ok[i] {
		e.capsulesInto(&kb.cbuf[i], &kb.pose[i])
		kb.ok[i] = true
	}
	return &kb.cbuf[i]
}

// blockCap is shape i num steps into the block (num = n is pose B).
func (e *engine) blockCap(kb *blocks, i, num int) capsule {
	b := e.blockCapsB(kb)[i]
	if num == kb.n {
		return b
	}
	a := &e.blockCapsA(kb)[i]
	f := float64(num) / float64(kb.n)
	b.a = lerpV(a.a, b.a, f)
	b.b = lerpV(a.b, b.b, f)
	return b
}

func (e *engine) blockCaps(kb *blocks, num int) caps {
	if num == kb.n {
		return *e.blockCapsB(kb)
	}
	var cs caps
	for i := range cs {
		cs[i] = e.blockCap(kb, i, num)
	}
	return cs
}

// blockVel is the velocity of shape i's end points during the block.
func (e *engine) blockVel(kb *blocks, i int) (vec, vec) {
	if !kb.velOK[i] {
		a := &e.blockCapsA(kb)[i]
		b := &e.blockCapsB(kb)[i]
		inv := 1 / (float64(kb.n) * simDT)
		kb.vel[i] = [2]vec{scale(sub(b.a, a.a), inv), scale(sub(b.b, a.b), inv)}
		kb.velOK[i] = true
	}
	return kb.vel[i][0], kb.vel[i][1]
}

// blockBox bounds part i over the rest of the block: its end points at the
// block's start and end (every interpolated position lies between them), or
// at the end alone on the block's last step, as the browser's outsideBox4.
func (e *engine) blockBox(kb *blocks, i, num int) *[6]float64 {
	if num == kb.n {
		if !kb.lastBoxOK[i] {
			c := &e.blockCapsB(kb)[i]
			boxInto(&kb.lastBox[i], c, c)
			kb.lastBoxOK[i] = true
		}
		return &kb.lastBox[i]
	}
	if !kb.boxOK[i] {
		boxInto(&kb.box[i], &e.blockCapsA(kb)[i], &e.blockCapsB(kb)[i])
		kb.boxOK[i] = true
	}
	return &kb.box[i]
}

// candSlack is how far the ball may move before the candidate parts are
// worked out again.
var candSlack = 0.1

// blockCands lists the parts whose swept box over the block, widened by the
// most that part can reach (collision radius, slow-ball reaction, late
// hands, the ball, a centimetre), comes within candSlack of the ball: no
// other part can pass the per-part test while the ball stays within
// candSlack of where the list was made, so the list is reused until then.
func (e *engine) blockCands(kb *blocks, p vec) *[nCaps]bool {
	if kb.candOK {
		q := kb.candP
		if p.x-q.x >= candSlack {
		} else if q.x-p.x >= candSlack {
		} else if p.y-q.y >= candSlack {
		} else if q.y-p.y >= candSlack {
		} else if p.z-q.z >= candSlack {
		} else if q.z-p.z >= candSlack {
		} else {
			return &kb.cand
		}
	}
	cb := e.blockCapsB(kb)
	px, py, pz := p.x, p.y, p.z
	for i := 0; i < nCaps; i++ {
		bx := e.blockBox(kb, i, 0) // start and end poses: covers the last step's box too
		c := &cb[i]
		m := ballR + c.hit + kReactReach + 0.01 + candSlack
		if c.kind == kindGlove {
			m += kHandLateMax
		}
		in := false
		if px < bx[0]-m {
		} else if px > bx[1]+m {
		} else if py < bx[2]-m {
		} else if py > bx[3]+m {
		} else if pz < bx[4]-m {
		} else if pz > bx[5]+m {
		} else {
			in = true
		}
		kb.cand[i] = in
	}
	kb.candP = p
	kb.candOK = true
	return &kb.cand
}

// blockBody bounds every part over the block (start and end poses), widened
// by the most any part reaches (e.maxReach).
func (e *engine) blockBody(kb *blocks) *[6]float64 {
	if !kb.bodyOK {
		bx := *e.blockBox(kb, 0, 0)
		for i := 1; i < nCaps; i++ {
			o := e.blockBox(kb, i, 0)
			if o[0] < bx[0] {
				bx[0] = o[0]
			}
			if o[1] > bx[1] {
				bx[1] = o[1]
			}
			if o[2] < bx[2] {
				bx[2] = o[2]
			}
			if o[3] > bx[3] {
				bx[3] = o[3]
			}
			if o[4] < bx[4] {
				bx[4] = o[4]
			}
			if o[5] > bx[5] {
				bx[5] = o[5]
			}
		}
		m := e.maxReach
		kb.body = [6]float64{bx[0] - m, bx[1] + m, bx[2] - m, bx[3] + m, bx[4] - m, bx[5] + m}
		kb.bodyOK = true
	}
	return &kb.body
}

// boxInto sets bx to the box of c0's and c1's end points: per axis the
// least and greatest of the four, found in pairs. (The browser keeps a
// running min and max; the two differ at most in the sign of a zero, which
// no comparison against the box can see.)
func boxInto(bx *[6]float64, c0, c1 *capsule) {
	a, b, c, d := c0.a, c0.b, c1.a, c1.b
	lo, hi := a.x, b.x
	if hi < lo {
		lo, hi = hi, lo
	}
	l2, h2 := c.x, d.x
	if h2 < l2 {
		l2, h2 = h2, l2
	}
	if l2 < lo {
		lo = l2
	}
	if h2 > hi {
		hi = h2
	}
	bx[0], bx[1] = lo, hi
	lo, hi = a.y, b.y
	if hi < lo {
		lo, hi = hi, lo
	}
	l2, h2 = c.y, d.y
	if h2 < l2 {
		l2, h2 = h2, l2
	}
	if l2 < lo {
		lo = l2
	}
	if h2 > hi {
		hi = h2
	}
	bx[2], bx[3] = lo, hi
	lo, hi = a.z, b.z
	if hi < lo {
		lo, hi = hi, lo
	}
	l2, h2 = c.z, d.z
	if h2 < l2 {
		l2, h2 = h2, l2
	}
	if l2 < lo {
		lo = l2
	}
	if h2 > hi {
		hi = h2
	}
	bx[4], bx[5] = lo, hi
}

func lerpV(p, q vec, f float64) vec {
	return vec{p.x + (q.x-p.x)*f, p.y + (q.y-p.y)*f, p.z + (q.z-p.z)*f}
}

// predictCrossing: where the keeper expects the ball to cross z = zk.
// (ballSpeed written out.)
func predictCrossing(b *ball, zk float64) pred {
	ux, uz := b.v.x, b.v.z
	if uz >= -0.5 {
		return pred{}
	}
	dz := zk - b.p.z
	if dz >= 0 {
		return pred{}
	}
	uy := b.v.y
	sh := fsqrt(ux*ux + uz*uz)
	s2 := ux*ux + uy*uy + uz*uz
	sp := b.sp
	if q := sp; !(q > 0) {
		sp = fsqrt(s2)
	} else if d, lim := s2-q*q, 0.01*s2; d > lim {
		sp = fsqrt(s2)
	} else if d < -lim {
		sp = fsqrt(s2)
	} else {
		sp = 0.5 * (q + s2/q)
	}
	dist := (dz / uz) * sh
	grounded := b.grounded
	roll := 0.0
	if grounded {
		roll = ballRollDecel
	}
	decel := dragK*sp*sh + roll
	tau := dist / sh
	if decel > 1e-9 {
		disc := sh*sh - 2*decel*dist
		if disc <= 0 {
			return pred{}
		}
		tau = (sh - fsqrt(disc)) / decel
	}
	y := ballR
	if !grounded {
		if y = b.p.y + uy*tau - 0.5*simG*tau*tau; y < ballR {
			y = ballR
		}
	}
	return pred{ok: true, x: b.p.x + (ux/sh)*dist, y: y, tau: tau}
}

func (e *engine) readLaunch(k *keeper, pr pred) vec {
	S := e.scale
	dx := pr.x - k.pos.x
	sgn := 1.0
	ax := dx
	if dx < 0 {
		sgn = -1
		ax = -dx
	}
	T := jsMax(0.15, pr.tau-kPushTime*0.5)
	need := jsMax(0, ax-kReadReach*S)
	vx := jsMin(e.p.DiveMax, need/T)
	if pr.y < 0.6*S && ax > 0.2 {
		vx = jsMax(vx, kLowDropSpeed)
	}
	jump := clamp((pr.y-0.9*S)*kReadHeightGn, e.p.JumpMin, e.p.JumpMax)
	return vec{sgn * vx, jump, 0.12 * vx}
}

func diveArms(side float64, jump float64, ln lean2) armPair {
	toBody := func(wx, wy float64) vec {
		return norm(vec{wx*ln.c - wy*ln.s, wx*ln.s + wy*ln.c, 0.1})
	}
	reach := (jump - kReachPivot) / kReachSpan
	lead := toBody(side, reach)
	trail := toBody(side, reach+0.45)
	if side > 0 {
		return armPair{trail, lead}
	}
	return armPair{lead, trail}
}

func (e *engine) commitLaunch(k *keeper, step int, t float64, lv vec, read bool) {
	k.phase = phasePush
	k.pushT = 0
	k.groundT = 0
	k.launchVel = lv
	lx := lv.x
	ly := jsMax(kLeanMin, lv.y+kLeanBias)
	l := fsqrt(lx*lx + ly*ly)
	k.leanTarget = lean2{lx / l, ly / l}
	ax := lx
	if lx < 0 {
		ax = -lx
	}
	star := ax < kStarSpeed && lv.y > 0.5
	if star {
		k.armsTarget = armsStar
	} else {
		side := -1.0
		if lx > 0 {
			side = 1
		}
		k.armsTarget = diveArms(side, lv.y, k.leanTarget)
	}
	k.commits = append(k.commits, Commit{Step: int(jsRound(t / simDT)), T0: t, VX: lx, Jump: lv.y, Star: star, Read: read})
	if ax >= kStarSpeed {
		side := 1.0
		bk := &e.body[1]
		if lx > 0 {
			side = -1
			bk = &e.body[0]
		}
		// That side's foot, as the browser takes it from keeperCapsules.
		foot := wpt(k.pos, k.lean, bk.footX, bk.footY, e.zeroZ)
		k.plant = plant{on: true, side: side, x: foot.x, y: foot.y, z: foot.z}
		k.plantUntil = t + kPushTime + kPlantExtra
	}
}

// trackArms steers both hands at the predicted crossing (body frame). The
// arithmetic is the browser's aim() and norm(), written out.
func (e *engine) trackArms(k *keeper, pr pred) {
	s, c := k.lean.s, k.lean.c
	sy := e.shY
	dz, dz2 := e.aimDZ, e.aimDZ2
	px, py := k.pos.x, k.pos.y
	sys, syc := sy*s, sy*c
	// Left hand, then right.
	sx := e.shXL
	wx := pr.x - (px + sx*c + sys)
	wy := pr.y - (py - sx*s + syc)
	var dx, dy, dd float64
	if l := fsqrt(wx*wx + wy*wy + dz2); l > 0 {
		inv := 1 / l
		dx, dy, dd = wx*inv, wy*inv, dz*inv
	}
	k.armsTarget.l = vec{dx*c - dy*s, dx*s + dy*c, dd}
	sx = e.shXR
	wx = pr.x - (px + sx*c + sys)
	wy = pr.y - (py - sx*s + syc)
	dx, dy, dd = 0, 0, 0
	if l := fsqrt(wx*wx + wy*wy + dz2); l > 0 {
		inv := 1 / l
		dx, dy, dd = wx*inv, wy*inv, dz*inv
	}
	k.armsTarget.r = vec{dx*c - dy*s, dx*s + dy*c, dd}
}

func lerpRange(r [2]float64, f float64) float64 { return r[0] + (r[1]-r[0])*f }

func (e *engine) diveEarliness(reaction float64) float64 {
	return clamp((e.p.ReactionMax-reaction)/(e.p.ReactionMax-e.p.ReactionMin), 0, 1)
}

func (e *engine) misjudge(k *keeper, lv vec, reaction float64) vec {
	if !k.mis.on {
		return lv
	}
	f := e.diveEarliness(reaction)
	vx := clamp(lv.x+k.mis.vx*lerpRange(kMisjudgeVX, f), -e.p.DiveMax, e.p.DiveMax)
	jump := clamp(lv.y+k.mis.jump*lerpRange(kMisjudgeJump, f), e.p.JumpMin, e.p.JumpMax)
	return vec{vx, jump, lv.z}
}

// readIdle reports whether nothing in a keeper step at t can act on the
// keeper's read: before kPerceive the hands do not track it, a keeper
// waiting to dive or diving does not use it, and one waiting to read uses it
// only from kReadBase + its reaction.
func readIdle(k *keeper, pl *Plan, t float64) bool {
	if t >= kPerceive {
		return false
	}
	switch k.phase {
	case phaseReady:
		return pl.Mode != ModeRead || t < kReadBase+pl.Reaction
	case phasePush, phaseAir:
		return true
	}
	return false
}

// perceive is the keeper's read of a predicted crossing at t: off by its
// misread, more the earlier it reads.
func (e *engine) perceive(k *keeper, pr pred, t float64) pred {
	if !pr.ok || !k.mis.on {
		return pr
	}
	f := clamp((e.misT1-t)/e.misTd, 0, 1)
	y := pr.y + k.mis.y*(e.misY0+e.misYd*f)
	if y < ballR {
		y = ballR
	}
	return pred{ok: true, x: pr.x + k.mis.x*(e.misX0+e.misXd*f), y: y, tau: pr.tau}
}

func (e *engine) keeperStep(k *keeper, pl *Plan, step int, t, dt float64, b *ball) {
	// It reads the ball every kReadEvery steps and acts on its latest read
	// in between; once it holds the ball it stops reading.
	fresh := false
	if !k.holding && step >= k.nextRead {
		k.nextRead = step + kReadEvery
		fresh = true
		if readIdle(k, pl, t) {
			// Nothing acts on this read before the next one (see readIdle):
			// keep what the keeper saw, worked out only if something does.
			k.seen, k.seenZ, k.seenT, k.pending = *b, k.pos.z, t, true
		} else {
			k.read = e.perceive(k, predictCrossing(b, k.pos.z), t)
			k.pending = false
		}
	}
	var pr pred
	if !k.holding {
		if k.pending && !readIdle(k, pl, t) {
			k.read = e.perceive(k, predictCrossing(&k.seen, k.seenZ), k.seenT)
			k.pending = false
		}
		pr = k.read
	} else {
		k.armsTarget = armsHold
	}

	if k.phase == phaseReady && !k.holding {
		if pl.Mode == ModeRead {
			if t >= kReadBase+pl.Reaction {
				if pr.ok && pr.tau <= kReadShuffleT {
					e.commitLaunch(k, step, t, e.readLaunch(k, pr), true)
				} else {
					k.phase = phaseRecover
				}
			}
		} else if t >= pl.Reaction {
			e.commitLaunch(k, step, t, e.misjudge(k, launchVelocity(pl), pl.Reaction), false)
		}
	}
	if fresh && t >= kPerceive && pr.ok {
		e.trackArms(k, pr)
	}

	leanRate := kLeanRate
	switch k.phase {
	case phasePush:
		k.pushT += dt
		f := jsMin(1, k.pushT/kPushTime)
		lv := k.launchVel
		k.vel = vec{lv.x * f, lv.y*f - simG*k.pushT, lv.z * f}
		if f >= 1 {
			k.phase = phaseAir
		}
	case phaseAir:
		k.vel.y -= simG * dt
	case phaseGround:
		sp := fsqrt(k.vel.x*k.vel.x + k.vel.z*k.vel.z)
		sc := 0.0
		if sp > 0 {
			sc = jsMax(0, sp-kSlideDecel*dt) / sp
		}
		k.vel = vec{k.vel.x * sc, 0, k.vel.z * sc}
		k.groundT += dt
		if k.groundT >= kRecoverDelay && !(pr.ok && pr.tau < kHoldDownT) {
			k.phase = phaseRecover
			k.leanTarget = lean2{0, 1}
		}
	case phaseRecover:
		leanRate = kRecoverLeanRt
		vx := k.vel.x
		vz := 0.0
		if k.lean.c > 0.35 {
			tx := k.pos.x
			if pr.ok {
				tx = clamp(pr.x, -e.p.GoalHalfWidth, e.p.GoalHalfWidth)
			}
			top := kRecoverSpeed * k.lean.c
			want := clamp((tx-k.pos.x)*5, -top, top)
			vx += clamp(want-vx, -kRecoverAccel*dt, kRecoverAccel*dt)
			vz = clamp((goalZ+kLineOffset-k.pos.z)*3, -1.5, 1.5)
		} else {
			vx = 0
		}
		k.vel = vec{vx, 0, vz}
		if len(k.commits) < kMaxCommits && k.lean.c > 0.55 && pr.ok && pr.tau < kRediveWindow {
			dx := pr.x - k.pos.x
			if dx > kRediveMinDX || dx < -kRediveMinDX || pr.y < 0.45 || pr.y > 1.9 {
				e.commitLaunch(k, step, t, e.readLaunch(k, pr), true)
			}
		}
	}
	kp, kv := &k.pos, &k.vel
	kp.x += kv.x * dt
	kp.y += kv.y * dt
	kp.z += kv.z * dt
	fl := leanRate * dt
	if fl >= 1 {
		fl = 1 // jsMin(1, fl) for a positive rate
	}
	ln, lt := &k.lean, &k.leanTarget
	ls, lc := ln.s+(lt.s-ln.s)*fl, ln.c+(lt.c-ln.c)*fl
	// nlerp2: three Newton steps towards unit length, as the browser.
	g := 1.5 - 0.5*(ls*ls+lc*lc)
	ls, lc = ls*g, lc*g
	g = 1.5 - 0.5*(ls*ls+lc*lc)
	ls, lc = ls*g, lc*g
	g = 1.5 - 0.5*(ls*ls+lc*lc)
	ln.s, ln.c = ls*g, lc*g
	rate := kArmRate
	if t >= kPerceive {
		rate = kArmTrackRate
	}
	fa := rate * dt
	if fa >= 1 {
		fa = 1
	}
	// blendUnit for each arm, written out. Each arm is replaced whole, not
	// updated field by field: the arms start as copies of armsReady, and a
	// gno struct copy shares its nested structs, so writing a.x in place
	// would write to this package's armsReady (which a realm may not do).
	a, b2 := &k.arms.l, &k.armsTarget.l
	x, y, z := a.x+(b2.x-a.x)*fa, a.y+(b2.y-a.y)*fa, a.z+(b2.z-a.z)*fa
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	x, y, z = x*g, y*g, z*g
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	x, y, z = x*g, y*g, z*g
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	*a = vec{x * g, y * g, z * g}
	a, b2 = &k.arms.r, &k.armsTarget.r
	x, y, z = a.x+(b2.x-a.x)*fa, a.y+(b2.y-a.y)*fa, a.z+(b2.z-a.z)*fa
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	x, y, z = x*g, y*g, z*g
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	x, y, z = x*g, y*g, z*g
	g = 1.5 - 0.5*(x*x+y*y+z*z)
	*a = vec{x * g, y * g, z * g}

	// The clearance depends on the lean alone (cached), and no lean puts it
	// above the keeper's scale: with the hips higher than that it cannot
	// matter.
	grounded := false
	if k.phase == phaseGround {
		grounded = true
	} else if k.phase == phaseRecover {
		grounded = true
	}
	clr := negInf
	if grounded || k.pos.y <= e.scale {
		stale := true
		if !k.clrOK {
		} else if k.clrS != k.lean.s {
		} else if k.clrC != k.lean.c {
		} else {
			stale = false
		}
		if stale {
			k.clr = e.clearance(k)
			k.clrS, k.clrC, k.clrOK = k.lean.s, k.lean.c, true
		}
		clr = k.clr
	}
	if grounded || k.pos.y < clr {
		k.pos = vec{k.pos.x, clr, k.pos.z}
		if k.phase == phaseAir {
			if k.vel.y <= 0 {
				k.phase = phaseGround
				k.groundT = 0
			}
		}
		if grounded {
			k.vel = vec{k.vel.x, 0, k.vel.z}
		} else if k.vel.y < 0 {
			k.vel = vec{k.vel.x, 0, k.vel.z}
		}
	}
	e.armsAboveGround(k)

	if k.plant.on {
		S := e.scale
		hx := k.pos.x + 0.11*k.plant.side*S*k.lean.c
		hy := k.pos.y - 0.11*k.plant.side*S*k.lean.s
		dx := k.plant.x - hx
		dy := k.plant.y - hy
		maxL := 0.85 * S * kPlantStretch
		if t > k.plantUntil || dx*dx+dy*dy > maxL*maxL {
			k.plant = plant{}
		}
	}
}

package physics

import "math"

// Outcomes.
const (
	Goal = 1
	Save = 2
	Miss = 3
	Post = 4
)

// Woodwork parts.
const (
	LeftPost  = 1
	RightPost = 2
	Crossbar  = 3
)

// Shot is the taker's input in the browser engine's units.
type Shot struct {
	AimX, AimY         float64 // m, point on the goal plane the swing heads for
	ContactX, ContactY float64 // ball radii
	Power              float64 // 0..1
	Mishit             [24]byte
	HasMishit          bool
}

// Launch is the ball as it leaves the boot.
type Launch struct {
	Vel, Spin          [3]float64
	Speed              float64
	FuzzX, FuzzY       float64 // contact error the mishit seed added, ball radii
	ContactX, ContactY float64 // where the boot actually met the ball
}

// Contact is one keeper touch, decided at its first contact.
type Contact struct {
	Step    int
	Part    int // index into PartNames
	Catch   bool
	GaveWay bool
}

// Result is a decided kick.
type Result struct {
	Outcome     int
	DecidedStep int     // the 1 kHz step it was decided in
	DecidedAt   float64 // s after contact
	Launch      Launch
	Touch       int // first part to touch the ball, -1 for none
	TouchStep   int
	Woodwork    int // first frame part it hit, 0 for none
	Caught      bool
	Pounced     bool // decided by the keeper pouncing on a loose ball
	Contacts    []Contact
	Commits     []Commit
	Misread     [4]float64 // the keeper's four normal draws (x, y, vx, jump)
	// Where the ball's centre first reached the goal line (rounded to the
	// millimetre, as the browser reports it), if it did.
	LineCross           bool
	LineT, LineX, LineY float64
	// Where it was when the whole ball was over the whole line, if it was.
	Crossing               bool
	CrossT, CrossX, CrossY float64
	EndX, EndY             float64 // the ball when the kick was decided, m
	Steps                  int
	Trace                  uint32 // see Options.Trace
}

// Options are for tests and analysis.
type Options struct {
	NoKeeper  bool // an empty goal
	NoMisread bool // a keeper that reads perfectly
	// Trace folds the state into Result.Trace every TraceEvery steps and at
	// the deciding step, for comparing with the browser engine bit for bit.
	Trace      bool
	TraceEvery int
}

type ball struct {
	p, v, w  vec
	grounded bool
	inGoal   bool
	held     bool
	sp       float64 // speed at the last drag evaluation (see ballSpeed)
}

// engine holds the constants derived from a game's Params.
type engine struct {
	p         Params
	body      [2]sideK
	headX     float64
	headY     float64
	headR     float64
	headH     float64
	zeroZ     float64
	scale     float64
	maxReach  float64
	standHipY float64
	netSideX  float64
	netRoofY  float64
	frame     [3]capsule

	// Per-game products the keeper's steps use, worked out once with the
	// browser's operations.
	shXL, shXR    float64 // kShoulderX * side * S, left and right
	shY           float64 // kShoulderY * S
	aimDZ, aimDZ2 float64 // 0.25 * S and its square: trackArms' forward offset
	gloveReachS   float64 // kGloveReach * S
	misT1, misTd  float64 // kMisreadT[1] and kMisreadT[1] - kMisreadT[0]
	misX0, misXd  float64 // lerpRange(kMisreadX, f) = misX0 + misXd*f
	misY0, misYd  float64
}

func newEngine(p Params) *engine {
	e := &engine{p: p, scale: p.KeeperScale}
	e.standHipY = kHipFactor * p.KeeperScale
	e.initBody()
	e.netSideX = p.GoalHalfWidth + postR
	e.netRoofY = p.GoalHeight + postR
	S := p.KeeperScale
	e.shXL, e.shXR = kShoulderX*-1.0*S, kShoulderX*1.0*S
	e.shY = kShoulderY * S
	e.aimDZ = 0.25 * S
	e.aimDZ2 = e.aimDZ * e.aimDZ
	e.gloveReachS = kGloveReach * S
	e.misT1, e.misTd = kMisreadT[1], kMisreadT[1]-kMisreadT[0]
	e.misX0, e.misXd = kMisreadX[0], kMisreadX[1]-kMisreadX[0]
	e.misY0, e.misYd = kMisreadY[0], kMisreadY[1]-kMisreadY[0]
	// The most any part reaches, plus the ball and a centimetre: the
	// thickest part's collision radius, slow-ball reaction and late hands.
	e.maxReach = ballR + jsMax(jsMax(0.14*p.KeeperScale+kMarginTorso, 0.08*p.KeeperScale+kMarginLeg),
		jsMax(kGloveR+kMarginGlove, 0.12*p.KeeperScale+kMarginHead)) + kReactReach + kHandLateMax + 0.01
	px := p.GoalHalfWidth + postR
	top := p.GoalHeight + postR
	e.frame = [3]capsule{
		{a: vec{-px, 0, goalZ}, b: vec{-px, top, goalZ}, r: postR, part: LeftPost},
		{a: vec{px, 0, goalZ}, b: vec{px, top, goalZ}, r: postR, part: RightPost},
		{a: vec{-px, top, goalZ}, b: vec{px, top, goalZ}, r: postR, part: Crossbar},
	}
	return e
}

// ---------------------------------------------------------------- the kick

type disc struct{ x, y float64 }

func clampDisc(x, y, max float64) disc {
	r2 := x*x + y*y
	if r2 <= max*max {
		return disc{x, y}
	}
	s := max / fsqrt(r2)
	return disc{x * s, y * s}
}

func mishitNormal(seed *[24]byte, offset int) float64 {
	sum := 0.0
	for i := 0; i < 6; i++ {
		sum += float64(u16(seed[:], offset+2*i)) / 65535
	}
	return (sum - 3) * sqrt2
}

const misreadSalt = 0x6b656570 // "keep"

func keeperMisread(seed *[24]byte) misread {
	m := mulberry{a: fnvBytes(0x811c9dc5^misreadSalt, seed[:])}
	normal := func() float64 {
		sum := 0.0
		for i := 0; i < 6; i++ {
			sum += m.next()
		}
		return (sum - 3) * sqrt2
	}
	x := normal()
	y := normal()
	vx := normal()
	jump := normal()
	return misread{on: true, x: x, y: y, vx: vx, jump: jump}
}

type launch struct {
	pos, vel, spin vec
	speed          float64
	fuzz           disc
	contact        disc
}

func (e *engine) computeLaunch(in *Shot) launch {
	pos := vec{0, ballR, 0}
	target := vec{clamp(in.AimX, -kickAimX, kickAimX), clamp(in.AimY, 0, kickAimY), goalZ}
	f := norm(sub(target, pos))
	right := norm(crossVec(f, upVec))
	up := crossVec(right, f)

	power := clamp(in.Power, 0, 1)
	intended := clampDisc(in.ContactX, in.ContactY, e.p.MaxContact)
	var fuzz disc
	if in.HasMishit {
		sigma := e.p.FuzzBase + e.p.FuzzPower*power
		fuzz.x = mishitNormal(&in.Mishit, 0) * sigma
		fuzz.y = mishitNormal(&in.Mishit, 12) * sigma
	}
	c := clampDisc(intended.x+fuzz.x, intended.y+fuzz.y, kickMaxStrike)
	cx, cy := c.x, c.y
	cz := fsqrt(1 - cx*cx - cy*cy)
	n := add(add(scale(right, cx), scale(up, cy)), scale(f, -cz))

	dir := norm(add(scale(f, 1-kickNormalMix), scale(n, -kickNormalMix)))
	quality := cz
	efficiency := 0.55 + 0.45*quality
	speed := (e.p.BallMinSpeed + (e.p.BallMaxSpeed-e.p.BallMinSpeed)*power) * efficiency
	vel := scale(dir, speed)

	rc := scale(n, ballR)
	dL := scale(crossVec(rc, scale(vel, ballM)), 1/ballI)
	side := dot(dL, up)
	backAxis := sub(dL, scale(up, side))
	spin := add(scale(up, side*kickSideSpin), scale(backAxis, kickBackSpin))
	sm := length(spin)
	if sm > kickMaxSpin {
		spin = scale(spin, kickMaxSpin/sm)
	}
	return launch{pos: pos, vel: vel, spin: spin, speed: speed, fuzz: fuzz, contact: c}
}

// ---------------------------------------------------------------- the ball

func rollingSpin(u vec) vec { return vec{u.z / ballR, 0, -u.x / ballR} }

func (e *engine) netAccel(b *ball) vec {
	p, u := b.p, b.v
	R := ballR
	K := netKs / ballM
	C := netCs / ballM
	ax, ay, az := 0.0, 0.0, 0.0
	touching := false
	panel := func(pen, vn float64) float64 {
		if pen <= 0 {
			return 0
		}
		touching = true
		k := K * netRecoil
		if vn < 0 {
			k = K
		}
		f := k*pen - C*vn
		if f > 0 {
			return f
		}
		return 0
	}
	az += panel(netBackZ-(p.z-R), u.z)
	ay -= panel(p.y+R-e.netRoofY, -u.y)
	sx := 1.0
	if p.x > 0 {
		sx = -1
	}
	ax += sx * panel(math.Abs(p.x)+R-e.netSideX, sx*u.x)
	if touching {
		ax -= netFriction * u.x
		ay -= netFriction * u.y
		az -= netFriction * u.z
	}
	return vec{ax, ay, az}
}

// ballSpeed is the ball's speed for drag: one Newton step from the speed of
// the previous evaluation while the speed has changed by under half a per
// cent, otherwise (the first step, after an impact) a square root.
func ballSpeed(b *ball, u vec) float64 {
	s2 := u.x*u.x + u.y*u.y + u.z*u.z
	s := b.sp
	d := s2 - s*s
	if s > 0 && d <= 0.01*s2 && d >= -0.01*s2 {
		return 0.5 * (s + s2/s)
	}
	return fsqrt(s2)
}

// heunBall is a free-flight step of dt (second-order Runge-Kutta), as the
// browser's: ballSpeed and airAccel written out.
func heunBall(b *ball, dt float64) {
	ux, uy, uz := b.v.x, b.v.y, b.v.z
	wx, wy, wz := b.w.x, b.w.y, b.w.z
	s2 := ux*ux + uy*uy + uz*uz
	sp := b.sp
	if q := sp; !(q > 0) {
		sp = fsqrt(s2)
	} else if d, lim := s2-q*q, 0.01*s2; d > lim {
		sp = fsqrt(s2)
	} else if d < -lim {
		sp = fsqrt(s2)
	} else {
		sp = 0.5 * (q + s2/q)
	}
	nk := -dragK * sp
	a1x := nk*ux + (wy*uz-wz*uy)*magnusK
	a1y := nk*uy - simG + (wz*ux-wx*uz)*magnusK
	a1z := nk*uz + (wx*uy-wy*ux)*magnusK
	vx, vy, vz := ux+a1x*dt, uy+a1y*dt, uz+a1z*dt
	f := 1 - ballSpinDecay*dt
	wx, wy, wz = wx*f, wy*f, wz*f
	s2 = vx*vx + vy*vy + vz*vz
	if q := sp; !(q > 0) {
		sp = fsqrt(s2)
	} else if d, lim := s2-q*q, 0.01*s2; d > lim {
		sp = fsqrt(s2)
	} else if d < -lim {
		sp = fsqrt(s2)
	} else {
		sp = 0.5 * (q + s2/q)
	}
	b.sp = sp
	nk = -dragK * sp
	a2x := nk*vx + (wy*vz-wz*vy)*magnusK
	a2y := nk*vy - simG + (wz*vx-wx*vz)*magnusK
	a2z := nk*vz + (wx*vy-wy*vx)*magnusK
	h := 0.5 * dt
	p := &b.p
	p.x += (ux + vx) * h
	p.y += (uy + vy) * h
	p.z += (uz + vz) * h
	b.v = vec{ux + (a1x+a2x)*h, uy + (a1y+a2y)*h, uz + (a1z+a2z)*h}
	b.w = vec{wx, wy, wz}
}

// integrateBall is the browser's semi-implicit Euler step, written out.
// (x += e rounds exactly as x = x + e, and is cheaper in gno.)
func (e *engine) integrateBall(b *ball, dt float64) {
	v := &b.v
	ux, uy, uz := v.x, v.y, v.z
	s2 := ux*ux + uy*uy + uz*uz
	sp := b.sp
	if q := sp; !(q > 0) {
		sp = fsqrt(s2)
	} else if d, lim := s2-q*q, 0.01*s2; d > lim {
		sp = fsqrt(s2)
	} else if d < -lim {
		sp = fsqrt(s2)
	} else {
		sp = 0.5 * (q + s2/q)
	}
	b.sp = sp
	nk := -dragK * sp
	ax, ay, az := nk*ux, nk*uy-simG, nk*uz
	grounded := b.grounded
	w := &b.w
	if !grounded {
		wx, wy, wz := w.x, w.y, w.z
		ax += (wy*uz - wz*uy) * magnusK
		ay += (wz*ux - wx*uz) * magnusK
		az += (wx*uy - wy*ux) * magnusK
	}
	if b.inGoal {
		n := e.netAccel(b)
		ax, ay, az = ax+n.x, ay+n.y, az+n.z
	}
	if grounded {
		if ay < 0 {
			ay = 0
		}
		if h := fsqrt(ux*ux + uz*uz); h > 0 {
			d := ballRollDecel // jsMin(ballRollDecel, h/dt), both positive
			if q := h / dt; q < d {
				d = q
			}
			ax -= (d * ux) / h
			az -= (d * uz) / h
		}
	}
	vx, vy, vz := ux+ax*dt, uy+ay*dt, uz+az*dt
	v.x, v.y, v.z = vx, vy, vz
	p := &b.p
	p.x += vx * dt
	p.y += vy * dt
	p.z += vz * dt
	if grounded {
		w.x, w.y, w.z = vz/ballR, w.y*(1-2*dt), -vx/ballR
	} else {
		f := 1 - ballSpinDecay*dt
		w.x *= f
		w.y *= f
		w.z *= f
	}
}

func groundContact(b *ball) float64 {
	if b.p.y >= ballR {
		return 0
	}
	b.p = vec{b.p.x, ballR, b.p.z}
	if b.v.y >= 0 {
		return 0
	}
	vy := -b.v.y
	if !b.grounded && vy > ballMinBounce {
		k := ballGroundKep
		b.v = vec{b.v.x * k, vy * ballEGround, b.v.z * k}
		b.w = add(scale(b.w, 0.5), scale(rollingSpin(b.v), 0.5))
		return vy
	}
	b.v = vec{b.v.x, 0, b.v.z}
	b.grounded = true
	return 0
}

type probe struct {
	ok       bool
	relSpeed float64
	dist     float64
}

func probeCapsule(b *ball, a, bb vec, r float64, va, vb vec) probe {
	ab := sub(bb, a)
	abab := dot(ab, ab)
	s := 0.0
	if abab > 0 {
		s = clamp(dot(sub(b.p, a), ab)/abab, 0, 1)
	}
	d := sub(b.p, add(a, scale(ab, s)))
	minD := ballR + r
	d2 := dot(d, d)
	if d2 >= minD*minD {
		return probe{}
	}
	dist := fsqrt(d2)
	n := vec{0, 0, 1}
	if dist > 1e-9 {
		n = scale(d, 1/dist)
	}
	sv := add(va, scale(sub(vb, va), s))
	rel := sub(b.v, sv)
	vn := dot(rel, n)
	if vn >= 0 {
		return probe{}
	}
	return probe{ok: true, relSpeed: length(rel), dist: dist}
}

type hit struct {
	ok          bool
	impactSpeed float64
	gaveWay     bool
}

// collideCapsule resolves the ball against a capsule moving with end
// velocities va, vb (nil in the browser for the goal frame: still). give < 0
// means the part never gives way (Infinity in the browser).
func collideCapsule(b *ball, a, bb vec, r float64, moving bool, va, vb vec, e, mu, spinKeep, give float64) hit {
	ab := sub(bb, a)
	abab := dot(ab, ab)
	s := 0.0
	if abab > 0 {
		s = clamp(dot(sub(b.p, a), ab)/abab, 0, 1)
	}
	q := add(a, scale(ab, s))
	d := sub(b.p, q)
	d2 := dot(d, d)
	minD := ballR + r
	if d2 >= minD*minD {
		return hit{}
	}
	dist := fsqrt(d2)
	n := vec{0, 0, 1}
	if dist > 1e-9 {
		n = scale(d, 1/dist)
	}
	sv := vec{0, 0, 0}
	if moving {
		sv = add(va, scale(sub(vb, va), s))
	}
	rel := sub(b.v, sv)
	vn := dot(rel, n)
	if vn >= 0 {
		b.p = add(q, scale(n, minD))
		return hit{}
	}
	relN := scale(n, vn)
	relT := sub(rel, relN)
	needed := -(1 + e) * vn
	if give >= 0 && needed > give {
		b.v = add(sv, add(scale(relT, 1-mu), scale(n, vn+give)))
		b.w = scale(b.w, spinKeep)
		return hit{ok: true, impactSpeed: -vn, gaveWay: true}
	}
	b.p = add(q, scale(n, minD))
	b.v = add(sv, sub(scale(relT, 1-mu), scale(relN, e)))
	b.w = scale(b.w, spinKeep)
	return hit{ok: true, impactSpeed: -vn}
}

// slowerThan is length(v) < s, taking the root only when it could be true.
func slowerThan(v vec, s float64) bool {
	d := v.x*v.x + v.y*v.y + v.z*v.z
	if d > s*s*1.01 {
		return false
	}
	return fsqrt(d) < s
}

// pounces reports whether the keeper gets to a loose ball before it is
// wholly over the line: slower than kPounceSpeed, within kPounceReach of the
// hips and below kPounceHeight, the keeper not mid-dive, and the ball needing
// longer to cross than the keeper needs to go down on it.
func pounces(k *keeper, b *ball) bool {
	if k.holding || k.phase == phasePush || k.phase == phaseAir || b.p.y > kPounceHeight {
		return false
	}
	dx, dy, dz := b.p.x-k.pos.x, b.p.y-k.pos.y, b.p.z-k.pos.z
	d2 := dx*dx + dy*dy + dz*dz
	if d2 >= kPounceReach*kPounceReach {
		return false
	}
	u := b.v
	if u.x*u.x+u.y*u.y+u.z*u.z >= kPounceSpeed*kPounceSpeed {
		return false
	}
	if u.z >= 0 {
		return true
	}
	// The keeper needs kPounceDelay plus the distance beyond kPounceNear at
	// kPounceMove: compared squared, as the browser does.
	over := goalZ - postR - ballR
	spare := (b.p.z-over)/-u.z - kPounceDelay
	if spare <= 0 {
		return false
	}
	reach := kPounceNear + spare*kPounceMove
	return d2 < reach*reach
}

// ------------------------------------------------------------ catch or parry

func segDist(p, a, b vec) float64 {
	ab := sub(b, a)
	abab := dot(ab, ab)
	s := 0.0
	if abab > 0 {
		s = clamp(dot(sub(p, a), ab)/abab, 0, 1)
	}
	return length(sub(p, add(a, scale(ab, s))))
}

func clamp01(x float64) float64 {
	if x < 0 {
		return 0
	}
	if x > 1 {
		return 1
	}
	return x
}

type decision struct {
	held   bool
	hands  float64
	toBody float64
}

func (e *engine) catchDecision(cs *caps, part *capsule, relSpeed float64, ballP vec) decision {
	S := e.scale
	gl := cs[3].a
	gr := cs[7].a
	mid := scale(add(gl, gr), 0.5)
	hx := ballP.x - mid.x
	hy := ballP.y - mid.y
	hands := 1 - clamp01((fsqrt(hx*hx+hy*hy)-kHandsGap*S)/((kHandsSpan-kHandsGap)*S))
	toBody := math.Inf(1)
	for i := range cs {
		if cs[i].kind == kindTorso {
			toBody = jsMin(toBody, segDist(ballP, cs[i].a, cs[i].b)-cs[i].r)
		}
	}
	body := 1 - clamp01((toBody-kBodyNear*S)/((kBodyFar-kBodyNear)*S))
	quality := kHandsWeight*hands + (1-kHandsWeight)*body
	limit := kCatchMin + (kCatchMax-kCatchMin)*quality
	if part.kind == kindGlove && hands < 0.5 {
		limit = jsMin(limit, kOneHandMax)
	}
	catchable := part.kind == kindGlove || part.kind == kindTorso
	if part.kind == kindLeg || part.kind == kindArm {
		catchable = true
		limit = kGatherSpeed
	} else if catchable && relSpeed <= kGatherSpeed && ballP.y < 0.6 {
		limit = jsMax(limit, kGatherSpeed)
	}
	return decision{held: catchable && relSpeed <= limit, hands: hands, toBody: toBody}
}

func (e *engine) holdPoint(cs *caps) vec {
	gl := cs[3].a
	gr := cs[7].a
	p := add(scale(add(gl, gr), 0.5), vec{0, 0, 0.06 * e.scale})
	return vec{p.x, jsMax(ballR, p.y), p.z}
}

// r3 is the browser's millimetre rounding: Math.round(x * 1000) / 1000.
func r3(x float64) float64 {
	return jsRound(x*1000) / 1000
}

// ---------------------------------------------------------------- simulate

// Work done only near the keeper or the goal frame (the browser engine has
// the same ZONES). A keeper part at full reach can touch the ball only
// within 1.97 m of the hip: the farthest part is a glove, 1.29 x scale from
// it, plus 0.35 m of collision margin, reaction reach and late hand reach,
// plus the ball's radius; the hip used is the keeper block's end pose, at
// most 14 cm from the interpolated one. Contacts are checked from probeZone
// out, posts and bar only within a centimetre of reach (nearFrame). Skipping checks that would find
// nothing leaves every result unchanged.
var (
	probeZone   = 2.2
	keeperBlock = 20 // steps per keeper step: it moves at 50 Hz
	ballBlock   = 5  // steps per ball step in free flight
)

// Simulate plays a kick to its verdict. plan is ignored with opt.NoKeeper.
func Simulate(in Shot, pl Plan, prm Params, opt Options) Result {
	e := newEngine(prm)
	withKeeper := !opt.NoKeeper
	ln := e.computeLaunch(&in)
	b := ball{p: ln.pos, v: ln.vel, w: ln.spin}
	res := Result{
		Touch: -1,
		Launch: Launch{
			Vel:   [3]float64{ln.vel.x, ln.vel.y, ln.vel.z},
			Spin:  [3]float64{ln.spin.x, ln.spin.y, ln.spin.z},
			Speed: ln.speed, FuzzX: ln.fuzz.x, FuzzY: ln.fuzz.y,
			ContactX: ln.contact.x, ContactY: ln.contact.y,
		},
	}
	var k keeper
	var kb blocks
	if withKeeper {
		var m misread
		if in.HasMishit && !opt.NoMisread {
			m = keeperMisread(&in.Mishit)
			res.Misread = [4]float64{m.x, m.y, m.vx, m.jump}
		}
		k = e.keeperInit(m)
		e.initCaps(&kb.cbuf[0])
		e.initCaps(&kb.cbuf[1])
		kb.pose[1] = poseOf(&k)
	}
	every := opt.TraceEvery
	if every <= 0 {
		every = 25
	}
	trace := uint32(0x811c9dc5)

	step := 0
	t := 0.0
	verdict := 0
	lastContact := -1.0
	var gaveWay [nParts]float64
	for i := range gaveWay {
		gaveWay[i] = negInf
	}
	woodworkSet := false
	touched := false // res.Touch >= 0 || woodworkSet
	tracing := opt.Trace

	// The bounds the loop tests against, worked out once with the same
	// operations as the browser's checks.
	near2 := probeZone * probeZone
	far := probeZone + 0.3
	far2 := far * far
	lowY := ballR + 0.15
	fr25 := ballR + postR + 0.25 // nearFrame(p, 0.25)
	nfr25 := -fr25
	fr01 := ballR + postR + 0.01 // nearFrame(p, 0.01)
	nfr01 := -fr01
	sideX, roofY := e.netSideX, e.netRoofY
	side25 := sideX + fr25
	side01 := sideX + fr01
	boardsIn := boardsZ - 0.3
	netZ := goalZ - postR
	netZ2 := goalZ - postR - 0.5
	crossZ := goalZ - postR - ballR
	awayZ := goalZ + 0.8
	wideX := sideX + ballR
	liftY := ballR + 0.005

	for verdict == 0 {
		if tracing && step%every == 0 {
			trace = foldState(trace, &b, withKeeper, &k)
		}
		px, py, pz := b.p.x, b.p.y, b.p.z
		// In free flight the ball moves in steps of ballBlock; this pass then
		// covers steps first..step. The browser's freeFlight, written out:
		// nothing the ball can touch within reach during the step, and the
		// step inside one keeper block.
		adv := 1
		if !b.held && !b.inGoal {
			// Comparisons are kept in if conditions: as operands of && and ||
			// gno converts each to bool at a cost.
			ff := true
			if withKeeper {
				dx, dy, dz := px-k.pos.x, py-k.pos.y, pz-k.pos.z
				if dx*dx+dy*dy+dz*dz < far2 {
					ff = false
				}
			}
			if !ff {
			} else if b.grounded {
			} else if py < lowY {
				ff = false
			}
			if !ff {
			} else if dz := pz - goalZ; dz > fr25 {
			} else if dz < nfr25 {
			} else {
				ax := px
				if px < 0 {
					ax = -px
				}
				if dx := ax - sideX; dx < fr25 {
					if dx > nfr25 {
						ff = false
					}
				}
				if !ff {
				} else if dy := py - roofY; dy < fr25 {
					if dy > nfr25 {
						if ax < side25 {
							ff = false
						}
					}
				}
			}
			if !ff {
			} else if withKeeper {
				first := step + 1
				end := kb.s0 + kb.n - 1
				if first >= kb.s0+kb.n {
					end = first + blockLen(&k, &pl, first) - 1
				}
				ff = first+ballBlock-1 <= end
			}
			if ff {
				adv = ballBlock
			}
		}
		first := step + 1
		step += adv
		t = float64(step) * simDT

		// The keeper moves in 50 Hz blocks; its shapes are only needed once
		// the ball is within reach (probeZone).
		near := false
		num := 0 // steps into the keeper's current block
		if withKeeper {
			if first >= kb.s0+kb.n {
				e.keeperBlock(&k, &pl, first, &b, &kb)
			}
			num = step - kb.s0 + 1
			dx, dy, dz := px-k.pos.x, py-k.pos.y, pz-k.pos.z
			if dx*dx+dy*dy+dz*dz < near2 {
				near = true
			}
		}

		if b.held {
			all := e.blockCaps(&kb, num)
			target := e.holdPoint(&all)
			f := jsMin(1, kHoldPull*simDT)
			np := add(b.p, scale(sub(target, b.p), f))
			b.v = scale(sub(np, b.p), 1/simDT)
			b.p = vec{np.x, jsMax(ballR, np.y), np.z}
			b.w = scale(b.w, jsMax(0, 1-20*simDT))
			continue
		}

		if adv == 1 {
			e.integrateBall(&b, simDT)
		} else if b.grounded {
			e.integrateBall(&b, float64(adv)*simDT)
		} else {
			heunBall(&b, float64(adv)*simDT)
		}
		if b.p.y < ballR {
			groundContact(&b)
		}
		px, py, pz = b.p.x, b.p.y, b.p.z

		// Posts and bar: only near them (nearFrame(p, 0.01), written out).
		frameNear := false
		if dz := pz - goalZ; dz > fr01 {
		} else if dz < nfr01 {
		} else {
			ax := px
			if px < 0 {
				ax = -px
			}
			if dx := ax - sideX; dx < fr01 {
				if dx > nfr01 {
					frameNear = true
				}
			}
			if frameNear {
			} else if dy := py - roofY; dy < fr01 {
				if dy > nfr01 {
					if ax < side01 {
						frameNear = true
					}
				}
			}
		}
		if frameNear {
			for i := range e.frame {
				c := &e.frame[i]
				h := collideCapsule(&b, c.a, c.b, c.r, false, vec{}, vec{}, ePost, 0.1, 0.7, -1)
				if h.ok && h.impactSpeed > 0.5 && !woodworkSet {
					woodworkSet = true
					touched = true
					res.Woodwork = c.part
				}
			}
			px, py, pz = b.p.x, b.p.y, b.p.z
		}

		near0 := near // within probeZone of the hips; pouncing needs kPounceReach, less
		// Clear of the whole body over the block, at any part's full reach:
		// every per-part check below would find nothing.
		if near {
			bd := e.blockBody(&kb)
			if px < bd[0] {
				near = false
			} else if px > bd[1] {
				near = false
			} else if py < bd[2] {
				near = false
			} else if py > bd[3] {
				near = false
			} else if pz < bd[4] {
				near = false
			} else if pz > bd[5] {
				near = false
			}
		}
		if near {
			sp := ballSpeed(&b, b.v)
			react := 0.0
			if t >= kPerceive && sp < kReactSpeed {
				react = kReactReach * (kReactSpeed - sp) / kReactSpeed
			}
			late := jsMin(kHandLateMax, kHandLateRate*jsMax(0, t-kPerceive-0.1))
			inAir := k.phase == phaseAir
			capsB := e.blockCapsB(&kb)
			cand := e.blockCands(&kb, b.p)
			for i := 0; i < nCaps; i++ {
				if !cand[i] {
					continue
				}
				cb := &capsB[i]
				if gaveWay[cb.part] > t {
					continue
				}
				// The browser adds 0 for the parts without the extra reach,
				// which leaves the (positive) radius as it is.
				reach := cb.hit
				if cb.kind != kindHead {
					reach += react
				}
				if cb.kind == kindGlove {
					reach += late
				}
				// Outside the box of the part's positions over the block by
				// more than the contact distance (plus a centimetre against
				// rounding) on any axis: the probe could only find nothing.
				bx := e.blockBox(&kb, i, num)
				m := ballR + reach + 0.01
				if px < bx[0]-m {
					continue
				} else if px > bx[1]+m {
					continue
				} else if py < bx[2]-m {
					continue
				} else if py > bx[3]+m {
					continue
				} else if pz < bx[4]-m {
					continue
				} else if pz > bx[5]+m {
					continue
				}
				cc := e.blockCap(&kb, i, num)
				c := &cc
				va, vb := e.blockVel(&kb, i)
				pr := probeCapsule(&b, c.a, c.b, reach, va, vb)
				if !pr.ok {
					continue
				}
				if res.Touch < 0 {
					res.Touch = c.part
					res.TouchStep = step
					touched = true
				}
				newTouch := t-lastContact > kTouchGap
				lastContact = t
				all := e.blockCaps(&kb, num)
				d := e.catchDecision(&all, c, pr.relSpeed, b.p)
				if newTouch && d.held && verdict == 0 && pz >= crossZ {
					res.Contacts = append(res.Contacts, Contact{Step: step, Part: c.part, Catch: true})
					res.Caught = true
					b.held = true
					b.grounded = false
					k.holding = true
					verdict, res.DecidedStep, res.DecidedAt = Save, step, t
					break
				}
				var give float64
				switch c.kind {
				case kindGlove:
					give = kGiveGlove
					if d.hands >= 0.5 {
						give = kGiveHands
					}
				case kindLeg:
					give = kGiveLeg
					if inAir {
						give = kGiveLegInAir
					}
				case kindArm:
					give = kGiveArm
				case kindTorso:
					give = kGiveTorso
				default:
					give = kGiveHead
				}
				if pr.dist > ballR+c.r {
					give *= kFingertipGive
				}
				if c.kind == kindGlove && d.toBody < kReflexBody*e.scale {
					give = jsMax(give, kGiveTorso)
				}
				el := kEBody
				if c.kind == kindGlove {
					el = kEGlove
				}
				h := collideCapsule(&b, c.a, c.b, reach, true, va, vb, el, kFriction, 0.4, give)
				px, py, pz = b.p.x, b.p.y, b.p.z
				if !h.ok {
					continue
				}
				if h.gaveWay {
					gaveWay[c.part] = t + kTouchGap
				}
				if !h.gaveWay && c.kind == kindGlove && pr.relSpeed < kParryControl && b.v.z < kParryOut {
					wide := -1.0
					if px >= k.pos.x {
						wide = 1
					}
					b.v = vec{b.v.x + wide*kParryWide, b.v.y, kParryOut}
				}
				if newTouch {
					res.Contacts = append(res.Contacts, Contact{Step: step, Part: c.part, GaveWay: h.gaveWay})
				}
			}
			if b.held {
				continue
			}
		}

		// The boards, the line and the net all lie at or behind the goal line.
		x, y, z := px, py, pz
		ax := x
		if x < 0 {
			ax = -x
		}
		if z <= goalZ {
			if z-ballR < boardsZ && z > boardsIn && b.v.z < 0 && y-ballR < boardsH && ax < boardsHW {
				b.p = vec{x, y, boardsZ + ballR}
				b.v = vec{b.v.x * 0.7, b.v.y * 0.7, -0.3 * b.v.z}
				z = b.p.z
			}
		}

		if b.grounded {
			if b.v.y > 0.3 {
				b.grounded = false
			} else if y > liftY {
				b.grounded = false
			}
		}

		if z <= goalZ {
			if !res.LineCross {
				res.LineCross = true
				res.LineT, res.LineX, res.LineY = r3(t), r3(x), r3(y)
			}
			if !b.inGoal && z < netZ && z > netZ2 && ax < sideX && y < roofY {
				b.inGoal = true
			}
			if !res.Crossing && z < crossZ {
				res.Crossing = true
				res.CrossT, res.CrossX, res.CrossY = r3(t), r3(x), r3(y)
				if b.inGoal {
					verdict = Goal
				} else if res.Touch >= 0 {
					verdict = Save
				} else if woodworkSet {
					verdict = Post
				} else {
					verdict = Miss
				}
				res.DecidedStep, res.DecidedAt = step, t
			}
		}

		if verdict == 0 {
			kept := false // decided without crossing the line
			if touched {
				if b.v.z > 0 {
					if z > awayZ {
						kept = true // parried away
					}
				}
			}
			if kept {
			} else if b.grounded && slowerThan(b.v, 0.15) {
				kept = true
			} else if ax > wideX {
				if x*b.v.x >= 0 {
					kept = true // outside a post and moving away from it
				}
			}
			if kept {
			} else if touched && withKeeper && near0 && pounces(&k, &b) {
				// The keeper pounces on the loose ball.
				verdict, res.DecidedStep, res.DecidedAt = Save, step, t
				b.v = vec{0, 0, 0}
				b.w = vec{0, 0, 0}
				res.Pounced = true
			} else if t >= simMaxT {
				kept = true
			}
			if kept {
				if res.Touch >= 0 {
					verdict = Save
				} else if woodworkSet {
					verdict = Post
				} else {
					verdict = Miss
				}
				res.DecidedStep, res.DecidedAt = step, t
			}
		}
	}
	if opt.Trace {
		trace = foldState(trace, &b, withKeeper, &k)
	}
	res.Outcome = verdict
	res.EndX, res.EndY = b.p.x, b.p.y
	res.Steps = step
	res.Trace = trace
	if withKeeper {
		res.Commits = k.commits
	}
	return res
}

// foldState hashes the ball and keeper state (FNV-1a over the float64 bits,
// big-endian), as the browser-side test harness does.
func foldState(h uint32, b *ball, withKeeper bool, k *keeper) uint32 {
	h = foldVec(h, b.p)
	h = foldVec(h, b.v)
	h = foldVec(h, b.w)
	if withKeeper {
		h = foldVec(h, k.pos)
		h = foldVec(h, k.vel)
		h = foldFloat(h, k.lean.s)
		h = foldFloat(h, k.lean.c)
		h = foldVec(h, k.arms.l)
		h = foldVec(h, k.arms.r)
	}
	return h
}

func foldVec(h uint32, v vec) uint32 {
	h = foldFloat(h, v.x)
	h = foldFloat(h, v.y)
	return foldFloat(h, v.z)
}

func foldFloat(h uint32, f float64) uint32 {
	u := math.Float64bits(f)
	for i := 0; i < 8; i++ {
		h ^= uint32(byte(u >> (56 - 8*uint(i))))
		h *= 0x01000193
	}
	return h
}

package physics

import "math"

// fsqrt is math.Sqrt, bit for bit, at a fraction of its gas.
//
// gno's math.Sqrt computes the root one bit at a time in interpreted code
// (~170k gas); the engine takes several roots every millisecond step. Here a
// float Newton iteration gets within a unit in the last place, and an exact
// integer test settles the last bit: for x = M * 2^e (e even) the correctly
// rounded root is R * 2^q, q = e/2 - 26, where R is the integer nearest
// sqrt(N), N = M * 2^52, and R is that integer exactly when
// R*R - R < N <= R*R + R (no square root of an integer lies halfway between
// two integers). N - R*R is small, so it is computed exactly mod 2^64. A
// Newton result one ulp off is moved by that ulp; anything else (rare) goes
// to sqrtSlow. Zero, subnormals, infinities and NaN go to math.Sqrt.
func fsqrt(x float64) float64 {
	b := math.Float64bits(x)
	if b-1<<52 >= 0x7fe0000000000000 { // negative, zero, subnormal, infinite or NaN
		return math.Sqrt(x)
	}
	y := math.Float64frombits((b >> 1) + 0x1ff8000000000000)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)
	yb := math.Float64bits(y)
	// x = m * 2^(ex), y = R * 2^q: y is the root when R*R - R < N <= R*R + R
	// for N = m * 2^(ex-2q), which is m << 52 or m << 53 when y is in the
	// root's binade.
	s := b>>52 - yb>>52<<1 + 1075
	if s-52 > 1 {
		return sqrtSlow(x)
	}
	R := yb&(1<<52-1) | 1<<52
	N := (b&(1<<52-1) | 1<<52) << s
	d := int64(N - R*R)
	if d > int64(R) {
		// One ulp low: R+1 is the root when N - (R+1)^2 = d - 2R - 1 is in range.
		if d2 := d - int64(R<<1) - 1; d2 <= int64(R+1) && d2 > -int64(R+1) && R+1 < 1<<53 {
			return math.Float64frombits(yb + 1)
		}
		return sqrtSlow(x)
	}
	if d <= -int64(R) {
		if d2 := d + int64(R<<1) - 1; d2 <= int64(R-1) && d2 > -int64(R-1) && R > 1<<52 {
			return math.Float64frombits(yb - 1)
		}
		return sqrtSlow(x)
	}
	return y
}

// sqrtSlow settles the roots the fast path cannot: the general case.
func sqrtSlow(x float64) float64 {
	b := math.Float64bits(x)
	exp := int(b>>52) & 0x7ff
	if b>>63 != 0 || exp == 0 || exp == 0x7ff {
		return math.Sqrt(x)
	}
	// Halve the exponent, then four Newton steps: within an ulp.
	y := math.Float64frombits((b >> 1) + 0x1ff8000000000000)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)
	y = 0.5 * (y + x/y)

	m := b&(1<<52-1) | 1<<52
	e := exp - 1075 // x = m * 2^e
	if e&1 != 0 {
		m <<= 1
		e--
	}
	N := m << 52
	yb := math.Float64bits(y)
	if int(yb>>52) != e/2+1049 { // y is not in the root's binade: settle it the long way
		return rootOf(N, e/2-26, y)
	}
	R := yb&(1<<52-1) | 1<<52 // y = R * 2^q
	d := int64(N - R*R)
	if d > int64(R) {
		if d2 := int64(N - (R+1)*(R+1)); d2 > int64(R+1) || d2 <= -int64(R+1) {
			return rootOf(N, e/2-26, y)
		}
		return math.Float64frombits(yb + 1)
	}
	if d <= -int64(R) {
		if R == 1<<52 {
			return rootOf(N, e/2-26, y)
		}
		if d2 := int64(N - (R-1)*(R-1)); d2 > int64(R-1) || d2 <= -int64(R-1) {
			return rootOf(N, e/2-26, y)
		}
		return math.Float64frombits(yb - 1)
	}
	return y
}

// rootOf is the general case: R from the estimate y, an integer Newton step,
// then whole units until R is the nearest integer to sqrt(N).
func rootOf(N uint64, q int, y float64) float64 {
	R := uint64(y * math.Float64frombits(uint64(1023-q)<<52))
	d := int64(N - R*R)
	R = uint64(int64(R) + d/int64(2*R))
	for {
		d = int64(N - R*R)
		if d > int64(R) {
			R++
		} else if d <= -int64(R) {
			R--
		} else {
			break
		}
	}
	return float64(R) * math.Float64frombits(uint64(q+1023)<<52)
}

// Package shots is a pay-to-play penalty shootout against the chain.
//
// A creator opens a game by choosing its keeper and ball constants and
// seeding the pot. A challenger joins an open game by paying its entry fee
// into the pot, then plays a shootout: in every round they take a kick
// (TakeShot) and then keep against the chain's kick (SubmitKeeperPlan). Five
// kicks each, finishing early when one side cannot be caught, then sudden
// death. Win, and the whole pot is paid out; lose, and the entry fee stays in
// the pot for the next challenger.
//
// Every kick is played out in the transaction that makes it: the player's
// choices are completed by 32 bytes derived from the block's timestamp (the
// chain's move and the mishit), and the outcome is penalty.SimulateShot of the
// ten inputs, recorded so anyone can re-run it. See impl/v1 for what that
// entropy does and does not guarantee.
//
// This realm's path and entry points are permanent. The rules engine is an
// implementation realm behind an upgradeable proxy
// (gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/upgradeable/v0); the games and their pots live here
// and survive every upgrade.
package shots

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shootout/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/upgradeable/v0"
)

// Impl is the rules engine. Declared here so every version agrees on one
// type identity. The methods are non-crossing: this realm threads its own cur
// in, so an implementation reaching Store is seen as this realm.
//
// The caller's address and the coins received are established by the entry
// points below and passed in; an implementation cannot be invoked with forged
// ones from elsewhere, because without this realm's live cur it cannot reach
// the state at all.
type Impl interface {
	CreateGame(_ int, rlm realm, creator address, deposit, entryFee, timeoutBlocks int64, config string) uint64
	JoinGame(_ int, rlm realm, player address, gameID uint64, paid int64)
	TopUp(_ int, rlm realm, from address, gameID uint64, paid int64)
	TakeShot(_ int, rlm realm, player address, gameID uint64, shot penalty.ShotInput) shootout.Kick
	SubmitKeeperPlan(_ int, rlm realm, player address, gameID uint64, plan penalty.KeeperPlan) shootout.Kick
	Forfeit(_ int, rlm realm, caller address, gameID uint64)
	CancelGame(_ int, rlm realm, caller address, gameID uint64)

	// SimulateShot is the pure outcome function: six taker inputs (in shot,
	// mishit seed included) and four keeper inputs, under cfg.
	SimulateShot(shot penalty.ShotParams, plan penalty.KeeperPlan, cfg penalty.Config) penalty.Result

	// Describe names the implementation for Render.
	Describe() string
}

// Denom is the coin pots are held in.
const Denom = "ugnot"

// Admin may accept, roll back or freeze an implementation. The value is the
// standard test1 account so the tests run unedited; set your own address
// before deploying (TransferAuthority moves it afterwards).
const Admin = address("g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm")

var (
	proxy    *upgradeable.Proxy
	selfPath string
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	proxy = upgradeable.New(upgradeable.NewAddrAuthority(Admin))
}

// ---------------------------------------------------------------- playing

// CreateGame opens a game. Send the initial pot with the call (ugnot).
// config overrides the default constants as "key=value,..." ("" for the
// defaults; see penalty.ParseConfig). timeoutBlocks 0 picks the default.
// Returns the game id.
func CreateGame(cur realm, entryFee, timeoutBlocks int64, config string) uint64 {
	paid := receivePayment(0, cur)
	return live().CreateGame(0, cur, cur.Previous().Address(), paid, entryFee, timeoutBlocks, config)
}

// JoinGame starts a shootout in an open game. Send exactly its entry fee.
func JoinGame(cur realm, gameID uint64) {
	paid := receivePayment(0, cur)
	live().JoinGame(0, cur, cur.Previous().Address(), gameID, paid)
}

// TopUp adds the coins sent to a game's pot.
func TopUp(cur realm, gameID uint64) {
	paid := receivePayment(0, cur)
	live().TopUp(0, cur, cur.Previous().Address(), gameID, paid)
}

// TakeShot plays the player's kick for the current round against the chain's
// keeper: aim point on the goal plane (mm), contact offset on the ball
// (milli-radii) and power (per-mille). Returns the kick as JSON.
func TakeShot(cur realm, gameID uint64, aimX, aimY, contactX, contactY, power int64) string {
	assertFreeDirectCall(0, cur)
	shot := penalty.ShotInput{AimX: aimX, AimY: aimY, ContactX: contactX, ContactY: contactY, Power: power}
	return kickJSON(live().TakeShot(0, cur, cur.Previous().Address(), gameID, shot))
}

// SubmitKeeperPlan plays the player's keeper plan against the chain's kick
// for the current round: four uint16 (see penalty.DecodePlan). Returns the
// kick as JSON.
func SubmitKeeperPlan(cur realm, gameID uint64, direction, speed, jump, reaction uint16) string {
	assertFreeDirectCall(0, cur)
	plan := penalty.KeeperPlan{Direction: direction, Speed: speed, Jump: jump, Reaction: reaction}
	return kickJSON(live().SubmitKeeperPlan(0, cur, cur.Previous().Address(), gameID, plan))
}

// Forfeit ends the current shootout as a loss: the player may resign at any
// time, anyone else once the player has been idle for the game's timeout.
func Forfeit(cur realm, gameID uint64) {
	assertFreeDirectCall(0, cur)
	live().Forfeit(0, cur, cur.Previous().Address(), gameID)
}

// CancelGame refunds the pot to the creator of a game nobody has played yet.
func CancelGame(cur realm, gameID uint64) {
	assertFreeDirectCall(0, cur)
	live().CancelGame(0, cur, cur.Previous().Address(), gameID)
}

// ---------------------------------------------------------------- reading

// SimulateShot runs the live outcome function on ten inputs, without touching
// any state: the taker's aim, contact, power and 48-hex-char mishit seed, and
// the keeper's four uint16, under config ("" for the defaults). Returns JSON.
func SimulateShot(aimX, aimY, contactX, contactY, power int64, mishitHex string,
	direction, speed, jump, reaction uint16, config string) string {
	cfg, err := penalty.ParseConfig(config)
	if err != nil {
		panic(err)
	}
	m, ok := penalty.ParseMishitHex(mishitHex)
	if !ok {
		panic("shots: mishit seed must be 48 hex characters")
	}
	shot := penalty.ShotInput{AimX: aimX, AimY: aimY, ContactX: contactX, ContactY: contactY, Power: power}.WithMishit(m)
	plan := penalty.KeeperPlan{Direction: direction, Speed: speed, Jump: jump, Reaction: reaction}
	return resultJSON(live().SimulateShot(shot, plan, cfg))
}

// GameJSON returns game id as JSON ("" if it does not exist).
func GameJSON(gameID uint64) string {
	g, ok := getGame(gameID)
	if !ok {
		return ""
	}
	return gameJSON(g)
}

// SessionJSON returns session no of a game, kicks included, as JSON.
func SessionJSON(gameID uint64, no int) string {
	s, ok := getSession(gameID, no)
	if !ok {
		return ""
	}
	return sessionJSON(s)
}

// ListGames returns up to limit games as a JSON array, newest first,
// optionally filtered by status ("open", "playing", "won", "cancelled"; ""
// for all).
func ListGames(status string, offset, limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	out := []string{}
	skipped := 0
	games.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*shootout.Game)
		if status != "" && g.Status.String() != status {
			return false
		}
		if skipped < offset {
			skipped++
			return false
		}
		out = append(out, gameJSON(*g))
		return len(out) >= limit
	})
	return "[" + strings.Join(out, ",") + "]"
}

// VerifySession re-runs every recorded kick of a shootout through the live
// outcome function and reports whether all of them reproduce, so anyone can
// check a result from the ten recorded inputs alone.
func VerifySession(gameID uint64, no int) bool {
	g, ok := getGame(gameID)
	if !ok {
		return false
	}
	s, ok := getSession(gameID, no)
	if !ok {
		return false
	}
	im := live()
	for _, k := range s.Kicks {
		if im.SimulateShot(k.Shot, k.Plan, g.Config) != k.Result {
			return false
		}
	}
	return true
}

// GameCount returns how many games have been created.
func GameCount() uint64 { return lastID }

// ---------------------------------------------------------------- guards

// receivePayment returns the ugnot sent with a direct user call. The coin
// envelope is credited to this realm only when this realm is the message's
// target, so a payment from any other call shape is refused rather than
// trusted.
func receivePayment(_ int, rlm realm) int64 {
	assertDirect(0, rlm)
	var amount int64
	for _, c := range unsafe.OriginSend() {
		if c.Denom != Denom {
			panic("shots: only " + Denom + " is accepted, got " + c.Denom)
		}
		amount += c.Amount
	}
	return amount
}

// assertFreeDirectCall requires a direct user call that sends no coins.
func assertFreeDirectCall(_ int, rlm realm) {
	assertDirect(0, rlm)
	if len(unsafe.OriginSend()) > 0 {
		panic("shots: this call does not accept coins")
	}
}

func assertDirect(_ int, rlm realm) {
	if !rlm.IsCurrent() || !rlm.Previous().IsUserCall() {
		panic("shots: call this directly from an account (no run scripts or other realms)")
	}
}

// ---------------------------------------------------------------- upgrades

// Register records the calling realm as a candidate implementation; an
// implementation calls it from its own init. Nothing serves until Accept.
func Register(cur realm, impl Impl) { proxy.Propose(0, cur, impl) }

// Accept makes the candidate at pkgPath live. Authority only.
func Accept(cur realm, pkgPath string) { proxy.Accept(0, cur, pkgPath) }

// Withdraw drops a candidate. Authority only, or the candidate itself.
func Withdraw(cur realm, pkgPath string) { proxy.Withdraw(0, cur, pkgPath) }

// Rollback restores the previous implementation. Authority only.
func Rollback(cur realm) { proxy.Rollback(0, cur) }

// Forget drops the rollback history. Authority only.
func Forget(cur realm) { proxy.Forget(0, cur) }

// Freeze ends upgradeability permanently. Authority only.
func Freeze(cur realm) { proxy.Freeze(0, cur) }

// AddExtension lets another realm act as this one. Authority only.
func AddExtension(cur realm, pkgPath string) { proxy.AddExtension(0, cur, pkgPath) }

// DropExtension revokes one. Authority only.
func DropExtension(cur realm, pkgPath string) { proxy.DropExtension(0, cur, pkgPath) }

// TransferAuthority hands the power to upgrade to another address.
func TransferAuthority(cur realm, newOwner address) {
	proxy.TransferAuthority(0, cur, upgradeable.NewAddrAuthority(newOwner))
}

// TransferAuthorityToRealms hands it to governance realms (comma-separated).
func TransferAuthorityToRealms(cur realm, csvPaths string) {
	paths := []string{}
	for _, p := range strings.Split(csvPaths, ",") {
		paths = append(paths, strings.TrimSpace(p))
	}
	proxy.TransferAuthority(0, cur, upgradeable.NewRealmAuthority(paths...))
}

func LivePath() string     { return proxy.LivePath() }
func Frozen() bool         { return proxy.Frozen() }
func Authority() string    { return proxy.Authority().String() }
func Extensions() []string { return proxy.Extensions() }

func PendingPaths() []string {
	out := []string{}
	for _, r := range proxy.Pending() {
		out = append(out, r.PkgPath())
	}
	return out
}

func HistoryPaths() []string {
	out := []string{}
	for _, r := range proxy.History() {
		out = append(out, r.PkgPath())
	}
	return out
}

func live() Impl {
	v, ok := proxy.TryImpl()
	if !ok {
		panic("shots: no implementation has been accepted yet")
	}
	im, ok := v.(Impl)
	if !ok {
		panic("shots: live implementation does not satisfy Impl")
	}
	return im
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package shots

import (
	"chain"
	"chain/banker"
	"strconv"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shootout/v0"
	"gno.land/p/nt/avl/v0"
)

// The game state lives here, at the permanent path, so accepting a new
// implementation changes the rules engine without moving a single pot.
//
// Implementations never hold references into it. They read copies through
// StateRef and write whole values back, so every mutation is performed by
// code declared in this realm and persists here.

var (
	games    = avl.NewTree() // gameKey(id) -> *shootout.Game
	sessions = avl.NewTree() // sessionKey(id, no) -> *shootout.Session
	lastID   uint64
)

func gameKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

func sessionKey(id uint64, no int) string {
	s := strconv.Itoa(no)
	for len(s) < 10 {
		s = "0" + s
	}
	return gameKey(id) + "/" + s
}

func getGame(id uint64) (shootout.Game, bool) {
	v := games.Get(gameKey(id))
	if v == nil {
		return shootout.Game{}, false
	}
	return *(v.(*shootout.Game)), true
}

func getSession(id uint64, no int) (shootout.Session, bool) {
	v := sessions.Get(sessionKey(id, no))
	if v == nil {
		return shootout.Session{}, false
	}
	s := *(v.(*shootout.Session))
	s.Kicks = append([]shootout.Kick(nil), s.Kicks...)
	return s, true
}

// StateRef is a permission to read and write the game state, handed to code
// running on this realm's cur. It carries the caller's realm value and
// re-checks it on every operation, so it cannot be stashed (the VM refuses to
// persist a realm value) or replayed after its frame returns.
type StateRef struct {
	rlm realm
}

// Store hands a StateRef to the live implementation, or to a registered
// extension. Any other realm presents its own cur and is refused.
func Store(_ int, rlm realm) *StateRef {
	assertStateAccess(0, rlm)
	return &StateRef{rlm: rlm}
}

// NewGameID allocates the next game id.
func (r *StateRef) NewGameID() uint64 {
	assertStateAccess(0, r.rlm)
	lastID++
	return lastID
}

// Game returns a copy of game id.
func (r *StateRef) Game(id uint64) (shootout.Game, bool) {
	assertStateAccess(0, r.rlm)
	return getGame(id)
}

// PutGame stores g (by value) under g.ID.
func (r *StateRef) PutGame(g shootout.Game) {
	assertStateAccess(0, r.rlm)
	if g.ID == 0 || g.ID > lastID {
		panic("shots: PutGame with an id that was never allocated")
	}
	c := g
	games.Set(gameKey(g.ID), &c)
}

// Session returns a copy of session no of game id, kicks included.
func (r *StateRef) Session(id uint64, no int) (shootout.Session, bool) {
	assertStateAccess(0, r.rlm)
	return getSession(id, no)
}

// PutSession stores s (by value, kicks copied).
func (r *StateRef) PutSession(s shootout.Session) {
	assertStateAccess(0, r.rlm)
	if _, ok := getGame(s.GameID); !ok || s.No <= 0 {
		panic("shots: PutSession for a game or session that does not exist")
	}
	c := s
	c.Kicks = append([]shootout.Kick(nil), s.Kicks...)
	sessions.Set(sessionKey(s.GameID, s.No), &c)
}

// Pay sends amount ugnot from this realm's balance to to.
func (r *StateRef) Pay(to address, amount int64) {
	assertStateAccess(0, r.rlm)
	if amount <= 0 {
		return
	}
	if !to.IsValid() {
		panic("shots: invalid payee address")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, r.rlm)
	bk.SendCoins(r.rlm.Address(), to, chain.NewCoins(chain.NewCoin(Denom, amount)))
}

// assertStateAccess panics unless rlm is a live cur belonging to this realm
// or to a registered extension.
func assertStateAccess(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("shots: realm value is not the caller's live cur")
	}
	if c := rlm.PkgPath(); c != selfPath && !proxy.IsExtension(c) {
		panic("shots: state is reachable only through " + selfPath +
			" or a registered extension, not from " + c)
	}
}

package shots

import (
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shootout/v0"
)

// ---------------------------------------------------------------- JSON

func q(s string) string { return strconv.Quote(s) }

func kv(k, v string) string { return q(k) + ":" + v }

func obj(fields ...string) string { return "{" + strings.Join(fields, ",") + "}" }

func gameJSON(g shootout.Game) string {
	return obj(
		kv("id", strconv.FormatUint(g.ID, 10)),
		kv("creator", q(string(g.Creator))),
		kv("status", q(g.Status.String())),
		kv("pot", itoa(g.Pot)),
		kv("entryFee", itoa(g.EntryFee)),
		kv("timeoutBlocks", itoa(g.TimeoutBlocks)),
		kv("config", q(g.Config.String())),
		kv("sessions", strconv.Itoa(g.Sessions)),
		kv("winner", q(string(g.Winner))),
		kv("createdHeight", itoa(g.CreatedHeight)),
		kv("closedHeight", itoa(g.ClosedHeight)),
	)
}

func resultJSON(r penalty.Result) string {
	return obj(
		kv("outcome", q(r.Outcome.String())),
		kv("x", itoa(r.X)),
		kv("y", itoa(r.Y)),
		kv("arrivalMs", itoa(r.ArrivalMS)),
		kv("ballSpeed", itoa(r.BallSpeed)),
		kv("mishitX", itoa(r.MishitX)),
		kv("mishitY", itoa(r.MishitY)),
		kv("keeper", q(r.Keeper.String())),
	)
}

func shotJSON(s penalty.ShotInput) string {
	return obj(kv("aimX", itoa(s.AimX)), kv("aimY", itoa(s.AimY)), kv("contactX", itoa(s.ContactX)),
		kv("contactY", itoa(s.ContactY)), kv("power", itoa(s.Power)))
}

func planJSON(p penalty.KeeperPlan) string {
	return obj(kv("direction", strconv.Itoa(int(p.Direction))), kv("speed", strconv.Itoa(int(p.Speed))),
		kv("jump", strconv.Itoa(int(p.Jump))), kv("reaction", strconv.Itoa(int(p.Reaction))))
}

func kickJSON(k shootout.Kick) string {
	return obj(
		kv("round", strconv.Itoa(k.Round)),
		kv("kicker", q(k.Kicker.String())),
		kv("shot", shotJSON(k.Shot.Input())),
		kv("mishit", q(penalty.MishitHex(k.Shot.Mishit))),
		kv("plan", planJSON(k.Plan)),
		kv("seed", q(k.Seed.Hex())),
		kv("result", resultJSON(k.Result)),
		kv("height", itoa(k.Height)),
		kv("time", itoa(k.Time)),
	)
}

func sessionJSON(s shootout.Session) string {
	kicks := make([]string, len(s.Kicks))
	for i, k := range s.Kicks {
		kicks[i] = kickJSON(k)
	}
	sc := s.Score
	return obj(
		kv("gameId", strconv.FormatUint(s.GameID, 10)),
		kv("no", strconv.Itoa(s.No)),
		kv("player", q(string(s.Player))),
		kv("status", q(s.Status.String())),
		kv("paid", itoa(s.Paid)),
		kv("score", obj(kv("playerKicks", strconv.Itoa(sc.PlayerKicks)), kv("playerGoals", strconv.Itoa(sc.PlayerGoals)),
			kv("chainKicks", strconv.Itoa(sc.ChainKicks)), kv("chainGoals", strconv.Itoa(sc.ChainGoals)))),
		kv("next", q(s.Next())),
		kv("kicks", "["+strings.Join(kicks, ",")+"]"),
		kv("joinHeight", itoa(s.JoinHeight)),
		kv("lastActionHeight", itoa(s.LastActionHeight)),
		kv("endHeight", itoa(s.EndHeight)),
	)
}

// ---------------------------------------------------------------- Render

// Render shows the games list, one game ("game/<id>") or one shootout
// ("game/<id>/<session>").
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) >= 2 && parts[0] == "game" {
		id, err := strconv.ParseUint(parts[1], 10, 64)
		if err != nil {
			return "# Not found\n"
		}
		if len(parts) >= 3 {
			no, err := strconv.Atoi(parts[2])
			if err != nil {
				return "# Not found\n"
			}
			return renderSession(id, no)
		}
		return renderGame(id)
	}
	return renderHome()
}

func ugnot(n int64) string {
	whole := n / 1000000
	frac := n % 1000000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := strconv.FormatInt(frac+1000000, 10)[1:]
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Spot Kick\n\nA pay-to-play penalty shootout against the chain. ")
	b.WriteString("Join an open game by paying its entry fee, then take five kicks and keep five. ")
	b.WriteString("Beat the chain and the pot is yours.\n\n")
	b.WriteString("| Game | Status | Pot | Entry | Challengers |\n|---|---|---:|---:|---:|\n")
	n := 0
	games.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*shootout.Game)
		id := strconv.FormatUint(g.ID, 10)
		b.WriteString("| [#" + id + "](:game/" + id + ") | " + g.Status.String() + " | " + ugnot(g.Pot) +
			" | " + ugnot(g.EntryFee) + " | " + strconv.Itoa(g.Sessions) + " |\n")
		n++
		return n >= 50
	})
	if n == 0 {
		b.WriteString("| _no games yet_ | | | | |\n")
	}
	b.WriteString("\nRules engine: ")
	if p := proxy.LivePath(); p != "" {
		b.WriteString("`" + p + "` — " + live().Describe() + "\n")
	} else {
		b.WriteString("_none accepted yet_\n")
	}
	return b.String()
}

func renderGame(id uint64) string {
	g, ok := getGame(id)
	if !ok {
		return "# Game not found\n"
	}
	sid := strconv.FormatUint(id, 10)
	var b strings.Builder
	b.WriteString("# Game #" + sid + "\n\n")
	b.WriteString("**" + g.Status.String() + "** · pot **" + ugnot(g.Pot) + "** · entry " + ugnot(g.EntryFee) +
		" · timeout " + itoa(g.TimeoutBlocks) + " blocks\n\n")
	b.WriteString("Created by `" + string(g.Creator) + "` at height " + itoa(g.CreatedHeight) + ".\n\n")
	if g.Status == shootout.GameWon {
		b.WriteString("Won by `" + string(g.Winner) + "` at height " + itoa(g.ClosedHeight) + ".\n\n")
	}
	b.WriteString("Constants: `" + g.Config.String() + "`\n\n")
	if g.Sessions > 0 {
		b.WriteString("## Challengers\n\n| # | Player | Status | Score |\n|---|---|---|---|\n")
		for no := g.Sessions; no >= 1 && no > g.Sessions-50; no-- {
			s, ok := getSession(id, no)
			if !ok {
				continue
			}
			sn := strconv.Itoa(no)
			b.WriteString("| [" + sn + "](:game/" + sid + "/" + sn + ") | `" + string(s.Player) + "` | " +
				s.Status.String() + " | " + score(s.Score) + " |\n")
		}
	}
	return b.String()
}

func score(s penalty.Shootout) string {
	return strconv.Itoa(s.PlayerGoals) + "/" + strconv.Itoa(s.PlayerKicks) + " – " +
		strconv.Itoa(s.ChainGoals) + "/" + strconv.Itoa(s.ChainKicks)
}

func renderSession(id uint64, no int) string {
	s, ok := getSession(id, no)
	if !ok {
		return "# Shootout not found\n"
	}
	var b strings.Builder
	b.WriteString("# Game #" + strconv.FormatUint(id, 10) + " · challenger " + strconv.Itoa(no) + "\n\n")
	b.WriteString("`" + string(s.Player) + "` · **" + s.Status.String() + "** · player " + score(s.Score) +
		" chain · next: " + s.Next() + "\n\n")
	b.WriteString("| Round | Kicker | Shot | Keeper plan | Outcome | At (mm) |\n|---|---|---|---|---|---|\n")
	for _, k := range s.Kicks {
		b.WriteString("| " + strconv.Itoa(k.Round) + " | " + k.Kicker.String() + " | " + k.Shot.Input().String() +
			" | " + k.Plan.String() + " (" + k.Result.Keeper.String() + ") | **" + k.Result.Outcome.String() +
			"** | " + itoa(k.Result.X) + ", " + itoa(k.Result.Y) + " |\n")
	}
	return b.String()
}

// Package impl is the first rules engine for gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shots.
//
// It owns the game state machine and pot rules; the state itself, and the
// coins, stay in the shots realm, reached through shots.Store.
//
// Game:    open --join--> playing --player wins--> won (pot paid out, closed)
//
//	^                 |
//	+----player loses-+ (entry fee stays in the pot)
//	open --creator cancels, nobody played yet--> cancelled (pot refunded)
//
// Session: each round the player shoots, then keeps. Every move is played
// out in the transaction that makes it, from 32 bytes derived from that
// block's timestamp (see entropy).
//
// ENTROPY. The seed is SHA-256 of the block time (unix nanoseconds) and the
// kick's identity (game, session, kick number), so two kicks in one block
// still differ. The block time is not known when the player signs, but it is
// not secret either: the proposer chooses it within consensus bounds, and
// anything else running in the same transaction can read the result. In
// particular a transaction that makes a move and then, in a later message,
// reads the session and fails on a bad outcome reverts the whole kick, so a
// player can retry until they like the result (for the price of gas). Fine
// for play money; a commit-reveal or a VRF is needed before real stakes, and
// an upgraded implementation can switch without touching games or pots.
package impl

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"strconv"
	"time"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/physics/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/penalty/v0"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shootout/v0"
	"gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/shots"
)

const (
	MinDeposit     = 1000000 // ugnot to seed a pot (1 GNOT)
	MinEntryFee    = 100000  // ugnot (0.1 GNOT)
	DefaultTimeout = 1000    // blocks a challenger may sit idle
	MinTimeout     = 30
	MaxTimeout     = 200000
)

type engine struct{}

var instance = &engine{}

// Instance returns the implementation, for a caller that registers it
// explicitly rather than relying on init.
func Instance() shots.Impl { return instance }

func init(cur realm) {
	shots.Register(cross(cur), instance)
}

func (e *engine) Describe() string {
	return "impl/v1: Spot Kick physics (penalty/physics/v0, bit-identical to the browser engine), seed = SHA-256 of the block time"
}

func (e *engine) SimulateShot(shot penalty.ShotParams, plan penalty.KeeperPlan, cfg penalty.Config) penalty.Result {
	return physics.SimulateShot(shot, plan, cfg)
}

// ---------------------------------------------------------------- games

func (e *engine) CreateGame(_ int, rlm realm, creator address, deposit, entryFee, timeoutBlocks int64, config string) uint64 {
	cfg, err := penalty.ParseConfig(config)
	if err != nil {
		panic(err)
	}
	if deposit < MinDeposit {
		panic("shots: send at least " + itoa(MinDeposit) + "ugnot to seed the pot")
	}
	if entryFee < MinEntryFee {
		panic("shots: the entry fee must be at least " + itoa(MinEntryFee) + "ugnot")
	}
	if timeoutBlocks == 0 {
		timeoutBlocks = DefaultTimeout
	}
	if timeoutBlocks < MinTimeout || timeoutBlocks > MaxTimeout {
		panic("shots: timeoutBlocks must be within " + itoa(MinTimeout) + ".." + itoa(MaxTimeout))
	}
	st := shots.Store(0, rlm)
	g := shootout.Game{
		ID:            st.NewGameID(),
		Creator:       creator,
		Config:        cfg,
		EntryFee:      entryFee,
		TimeoutBlocks: timeoutBlocks,
		Pot:           deposit,
		Status:        shootout.GameOpen,
		CreatedHeight: runtime.ChainHeight(),
	}
	st.PutGame(g)
	chain.Emit("GameCreated", "game", u64(g.ID), "creator", string(creator), "pot", itoa(deposit),
		"entryFee", itoa(entryFee), "config", cfg.String())
	return g.ID
}

func (e *engine) TopUp(_ int, rlm realm, from address, gameID uint64, paid int64) {
	st := shots.Store(0, rlm)
	g := mustGame(st, gameID)
	if g.Status != shootout.GameOpen && g.Status != shootout.GamePlaying {
		panic("shots: game " + u64(gameID) + " is closed")
	}
	if paid <= 0 {
		panic("shots: send ugnot to top up the pot")
	}
	g.Pot += paid
	st.PutGame(g)
	chain.Emit("PotToppedUp", "game", u64(gameID), "from", string(from), "amount", itoa(paid), "pot", itoa(g.Pot))
}

func (e *engine) CancelGame(_ int, rlm realm, caller address, gameID uint64) {
	st := shots.Store(0, rlm)
	g := mustGame(st, gameID)
	if caller != g.Creator {
		panic("shots: only the creator can cancel game " + u64(gameID))
	}
	if g.Status != shootout.GameOpen || g.Sessions > 0 {
		panic("shots: a game can only be cancelled before anyone has played it")
	}
	refund := g.Pot
	g.Pot = 0
	g.Status = shootout.GameCancelled
	g.ClosedHeight = runtime.ChainHeight()
	st.PutGame(g)
	st.Pay(g.Creator, refund)
	chain.Emit("GameCancelled", "game", u64(gameID), "refund", itoa(refund))
}

// ---------------------------------------------------------------- sessions

func (e *engine) JoinGame(_ int, rlm realm, player address, gameID uint64, paid int64) {
	st := shots.Store(0, rlm)
	g := mustGame(st, gameID)
	if g.Status != shootout.GameOpen {
		panic("shots: game " + u64(gameID) + " is not open (" + g.Status.String() + ")")
	}
	if paid != g.EntryFee {
		panic("shots: send exactly the entry fee, " + itoa(g.EntryFee) + "ugnot")
	}
	h := runtime.ChainHeight()
	g.Pot += paid
	g.Sessions++
	g.Status = shootout.GamePlaying
	st.PutGame(g)
	st.PutSession(shootout.Session{
		GameID:           gameID,
		No:               g.Sessions,
		Player:           player,
		Paid:             paid,
		Status:           shootout.SessionPlaying,
		JoinHeight:       h,
		LastActionHeight: h,
	})
	chain.Emit("GameJoined", "game", u64(gameID), "session", strconv.Itoa(g.Sessions), "player", string(player),
		"pot", itoa(g.Pot))
}

func (e *engine) TakeShot(_ int, rlm realm, player address, gameID uint64, shot penalty.ShotInput) shootout.Kick {
	st := shots.Store(0, rlm)
	g, s := mustPlayersSession(st, gameID, player)
	if err := shot.Validate(g.Config); err != nil {
		panic(err)
	}
	return e.kick(st, g, s, penalty.SidePlayer, shot, penalty.KeeperPlan{})
}

func (e *engine) SubmitKeeperPlan(_ int, rlm realm, player address, gameID uint64, plan penalty.KeeperPlan) shootout.Kick {
	st := shots.Store(0, rlm)
	g, s := mustPlayersSession(st, gameID, player)
	return e.kick(st, g, s, penalty.SideChain, penalty.ShotInput{}, plan)
}

// kick plays the player's move against the chain's, both completed by this
// block's seed, records it, and ends the session if the shootout is decided.
func (e *engine) kick(st *shots.StateRef, g shootout.Game, s shootout.Session, kicker penalty.Side,
	shot penalty.ShotInput, plan penalty.KeeperPlan) shootout.Kick {
	if want := s.Score.Next(); want != kicker {
		if want == penalty.SidePlayer {
			panic("shots: it is your turn to shoot (TakeShot)")
		}
		panic("shots: it is your turn to keep (SubmitKeeperPlan)")
	}
	h := runtime.ChainHeight()
	now := time.Now().UnixNano()
	seed := entropy(g, s, now)
	k := shootout.Kick{
		Round:  s.Score.Round(),
		Kicker: kicker,
		Seed:   seed,
		Height: h,
		Time:   now,
	}
	if kicker == penalty.SidePlayer {
		// The player shoots; the seed is the chain's keeper and the mishit.
		k.Shot = shot.WithMishit(seed.Mishit())
		k.Plan = seed.KeeperPlan()
	} else {
		// The player keeps; the seed is the chain's kick and its mishit.
		k.Shot = seed.ChainShot(g.Config).WithMishit(seed.Mishit())
		k.Plan = plan
	}
	k.Result = e.SimulateShot(k.Shot, k.Plan, g.Config)
	s.Kicks = append(s.Kicks, k)
	s.Score.Record(kicker, k.Result.Outcome.Scored())
	s.LastActionHeight = h
	chain.Emit("Kick", "game", u64(g.ID), "session", strconv.Itoa(s.No), "round", strconv.Itoa(k.Round),
		"kicker", kicker.String(), "outcome", k.Result.Outcome.String(), "seed", seed.Hex())

	switch s.Score.Winner() {
	case penalty.SidePlayer:
		prize := g.Pot
		s.Status = shootout.SessionWon
		s.EndHeight = h
		g.Pot = 0
		g.Status = shootout.GameWon
		g.Winner = s.Player
		g.ClosedHeight = h
		st.PutGame(g)
		st.PutSession(s)
		st.Pay(s.Player, prize)
		chain.Emit("PotWon", "game", u64(g.ID), "session", strconv.Itoa(s.No), "player", string(s.Player),
			"prize", itoa(prize))
		return k
	case penalty.SideChain:
		s.Status = shootout.SessionLost
		s.EndHeight = h
		g.Status = shootout.GameOpen
		chain.Emit("SessionLost", "game", u64(g.ID), "session", strconv.Itoa(s.No), "player", string(s.Player),
			"pot", itoa(g.Pot))
	}
	st.PutGame(g)
	st.PutSession(s)
	return k
}

func (e *engine) Forfeit(_ int, rlm realm, caller address, gameID uint64) {
	st := shots.Store(0, rlm)
	g := mustGame(st, gameID)
	if g.Status != shootout.GamePlaying {
		panic("shots: nobody is playing game " + u64(gameID))
	}
	s, _ := session(st, gameID, g.Sessions)
	h := runtime.ChainHeight()
	if caller != s.Player && h-s.LastActionHeight <= g.TimeoutBlocks {
		panic("shots: the player has " + itoa(g.TimeoutBlocks-(h-s.LastActionHeight)+1) +
			" more blocks before they can be forfeited")
	}
	s.Status = shootout.SessionForfeited
	s.EndHeight = h
	g.Status = shootout.GameOpen
	st.PutGame(g)
	st.PutSession(s)
	chain.Emit("SessionForfeited", "game", u64(gameID), "session", strconv.Itoa(s.No),
		"player", string(s.Player), "by", string(caller), "pot", itoa(g.Pot))
}

// entropy is the kick's 32-byte seed: SHA-256 of the block time and the
// kick's identity (see the package comment for what that does and does not
// guarantee).
func entropy(g shootout.Game, s shootout.Session, blockTime int64) penalty.Seed {
	var b [8]byte
	for i := 0; i < 8; i++ {
		b[i] = byte(uint64(blockTime) >> (56 - 8*uint(i)))
	}
	id := "|" + u64(g.ID) + "|" + strconv.Itoa(s.No) + "|" + strconv.Itoa(len(s.Kicks))
	return penalty.Seed(sha256.Sum256(append(b[:], []byte(id)...)))
}

// ---------------------------------------------------------------- helpers

func mustGame(st *shots.StateRef, id uint64) shootout.Game {
	g, ok := st.Game(id)
	if !ok {
		panic("shots: no game " + u64(id))
	}
	return ownGame(g)
}

// session reads the live session of a game as this realm's own copy.
func session(st *shots.StateRef, id uint64, no int) (shootout.Session, bool) {
	s, ok := st.Session(id, no)
	if !ok {
		return s, false
	}
	return ownSession(s), true
}

// ownGame and ownSession rebuild values read through shots.Store in this
// realm. What Store hands back was allocated by the shots realm, and the VM
// refuses writes to another realm's objects (a pointer-method update such as
// Shootout.Record trips its cross-realm check), so the engine only ever
// mutates copies it built itself; PutGame/PutSession copy them back.
func ownGame(g shootout.Game) shootout.Game {
	return shootout.Game{
		ID:            g.ID,
		Creator:       g.Creator,
		Config:        g.Config,
		EntryFee:      g.EntryFee,
		TimeoutBlocks: g.TimeoutBlocks,
		Pot:           g.Pot,
		Status:        g.Status,
		Sessions:      g.Sessions,
		Winner:        g.Winner,
		CreatedHeight: g.CreatedHeight,
		ClosedHeight:  g.ClosedHeight,
	}
}

func ownSession(s shootout.Session) shootout.Session {
	kicks := make([]shootout.Kick, len(s.Kicks))
	for i := range s.Kicks {
		kicks[i] = s.Kicks[i]
	}
	return shootout.Session{
		GameID: s.GameID,
		No:     s.No,
		Player: s.Player,
		Paid:   s.Paid,
		Score: penalty.Shootout{
			PlayerKicks: s.Score.PlayerKicks,
			PlayerGoals: s.Score.PlayerGoals,
			ChainKicks:  s.Score.ChainKicks,
			ChainGoals:  s.Score.ChainGoals,
		},
		Kicks:            kicks,
		Status:           s.Status,
		JoinHeight:       s.JoinHeight,
		LastActionHeight: s.LastActionHeight,
		EndHeight:        s.EndHeight,
	}
}

func mustPlayersSession(st *shots.StateRef, gameID uint64, player address) (shootout.Game, shootout.Session) {
	g := mustGame(st, gameID)
	if g.Status != shootout.GamePlaying {
		panic("shots: nobody is playing game " + u64(gameID) + "; join it first")
	}
	s, ok := session(st, gameID, g.Sessions)
	if !ok || s.Player != player {
		panic("shots: you are not the challenger in game " + u64(gameID))
	}
	if s.Status != shootout.SessionPlaying {
		panic("shots: your shootout in game " + u64(gameID) + " is over")
	}
	return g, s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }
func u64(n uint64) string { return strconv.FormatUint(n, 10) }
